import {
  useEffect,
  useRef,
  useState,
} from "react";

import {
  useLocation,
  useNavigate,
} from "react-router-dom";

import {
  FiGrid,
  FiCalendar,
  FiBox,
  FiShoppingCart,
  FiUsers,
  FiHome,
  FiTruck,
  FiCornerUpLeft,
  FiFileText,
  FiSettings,
  FiChevronDown,
  FiMenu,
  FiX,
  FiLogOut,
} from "react-icons/fi";

import {
  useTranslation,
} from "react-i18next";

import {
  useAuth,
} from "../../context/AuthContext";

import {
  useDialog,
} from "../../context/DialogContext";
import BitesLogo from "../../assets/images/bites-logo.png";
const menuItems = [
  ["Dashboard", "Dashboard", FiGrid, "/dashboard", "dashboard"],
  ["Events", "Events", FiCalendar, "/events", "events"],
  ["Items", "Items", FiBox, "/items", "items"],
  ["Purchase", "Purchase", FiShoppingCart, "/purchase", "purchase"],
  ["Suppliers", "Suppliers", FiUsers, "/suppliers", "suppliers"],
  ["Warehouse", "Warehouse", FiHome, "/warehouse", "warehouse"],
  ["Staff", "Staff", FiUsers, "/staff", "staff"],
  ["Dispatch", "Dispatch", FiTruck, "/dispatch", "dispatch"],
  ["Returns", "Returns", FiCornerUpLeft, "/returns", "returns"],
  ["Reports", "Reports", FiFileText, "/reports", "reports"],
].map(
  ([
    title,
    moduleName,
    icon,
    path,
    pageName,
  ]) => ({
    title,
    moduleName,
    icon,
    path,
    pageName,
  })
);

menuItems.push({
  title: "Settings",
  anyOfModules: [
    "Settings",
    "Users / Role",
  ],
  icon: FiSettings,
  path: "/settings",
  pageName: "settings",
});

export default function Sidebar({
  activePage = "dashboard",
}) {
  const navigate =
    useNavigate();

  const location =
    useLocation();

  const {
    t,
  } = useTranslation();

  const {
    profile,
    isAdmin,
    hasPermission,
    hasAnyPermission,
    signOut,
  } = useAuth();

  const {
    showAlert,
    showConfirm,
  } = useDialog();

  const userMenuRef =
    useRef(null);

  const [
    isSidebarOpen,
    setIsSidebarOpen,
  ] = useState(false);

  const [
    isUserMenuOpen,
    setIsUserMenuOpen,
  ] = useState(false);

  const [
    signingOut,
    setSigningOut,
  ] = useState(false);

  const visibleMenuItems =
    menuItems.filter((item) => {
      if (isAdmin) {
        return true;
      }

      if (item.anyOfModules) {
        return hasAnyPermission(
          item.anyOfModules,
          "view"
        );
      }

      return hasPermission(
        item.moduleName,
        "view"
      );
    });

  const closeSidebar = () => {
    setIsSidebarOpen(false);
  };

  const closeUserMenu = () => {
    setIsUserMenuOpen(false);
  };

  const handleNavigation = (
    path
  ) => {
    navigate(path);
    closeSidebar();
    closeUserMenu();
  };

  const handleLogout = async () => {
    closeUserMenu();

    const confirmed =
      await showConfirm({
        title: t("sidebar.logout"),
        message:
          t("sidebar.logoutConfirm"),
        confirmText:
          t("sidebar.logout"),
        cancelText:
          t("sidebar.cancel"),
        type: "warning",
      });

    if (!confirmed) {
      return;
    }

    try {
      setSigningOut(true);

      const result =
        await signOut();

      if (!result?.success) {
        throw (
          result?.error ||
          new Error(
            "Could not logout."
          )
        );
      }

      navigate(
        "/login",
        {
          replace: true,
        }
      );
    } catch (error) {
      await showAlert({
        title:
          t("sidebar.logoutFailed"),
        message:
          error.message ||
          t("sidebar.couldNotLogout"),
        type: "error",
      });
    } finally {
      setSigningOut(false);
    }
  };

  useEffect(() => {
    closeSidebar();
    closeUserMenu();
  }, [location.pathname]);

  useEffect(() => {
    const handleEscape = (
      event
    ) => {
      if (
        event.key === "Escape"
      ) {
        closeSidebar();
        closeUserMenu();
      }
    };

    window.addEventListener(
      "keydown",
      handleEscape
    );

    return () => {
      window.removeEventListener(
        "keydown",
        handleEscape
      );
    };
  }, []);

  useEffect(() => {
    const handleOutsideClick = (
      event
    ) => {
      if (
        userMenuRef.current &&
        !userMenuRef.current.contains(
          event.target
        )
      ) {
        closeUserMenu();
      }
    };

    document.addEventListener(
      "mousedown",
      handleOutsideClick
    );

    return () => {
      document.removeEventListener(
        "mousedown",
        handleOutsideClick
      );
    };
  }, []);

  useEffect(() => {
    document.body.classList.toggle(
      "dashboard-sidebar-is-open",
      isSidebarOpen
    );

    return () => {
      document.body.classList.remove(
        "dashboard-sidebar-is-open"
      );
    };
  }, [isSidebarOpen]);

  return (
    <>
      <button
        type="button"
        className="dashboard-mobile-menu-button"
        onClick={() =>
          setIsSidebarOpen(
            (current) =>
              !current
          )
        }
        aria-label={
          isSidebarOpen
            ? t("sidebar.closeSidebar")
            : t("sidebar.openSidebar")
        }
        aria-expanded={
          isSidebarOpen
        }
      >
        {isSidebarOpen ? (
          <FiX />
        ) : (
          <FiMenu />
        )}
      </button>

      <button
        type="button"
        className={`dashboard-sidebar-overlay ${
          isSidebarOpen
            ? "show"
            : ""
        }`}
        onClick={
          closeSidebar
        }
        aria-label={
          t("sidebar.closeSidebar")
        }
      />

      <aside
        className={`dashboard-sidebar ${
          isSidebarOpen
            ? "mobile-open"
            : ""
        }`}
      >
        <div className="sidebar-top">
          <button
            type="button"
            className="dashboard-logo"
            onClick={() => {
              const firstPath =
                visibleMenuItems[0]
                  ?.path;

              if (firstPath) {
                handleNavigation(
                  firstPath
                );
              }
            }}
          >
            <img
  src={BitesLogo}
  alt="Bites"
  className="dashboard-logo-image"
/>
          </button>

          <nav
            className="sidebar-nav"
            aria-label={
              t(
                "sidebar.dashboardNavigation"
              )
            }
          >
            <ul className="dashboard-menu">
              {visibleMenuItems.map(
                (item) => {
                  const Icon =
                    item.icon;

                  const isActive =
                    activePage ===
                    item.pageName;

                  return (
                    <li
                      key={
                        item.pageName
                      }
                      className={
                        isActive
                          ? "active"
                          : ""
                      }
                    >
                      <button
                        type="button"
                        className="dashboard-menu-button"
                        onClick={() =>
                          handleNavigation(
                            item.path
                          )
                        }
                        aria-current={
                          isActive
                            ? "page"
                            : undefined
                        }
                      >
                        <span className="dashboard-menu-icon">
                          <Icon />
                        </span>

                        <span className="dashboard-menu-text">
                          {t(
                            `sidebar.${item.pageName}`
                          )}
                        </span>
                      </button>
                    </li>
                  );
                }
              )}
            </ul>
          </nav>
        </div>

        <div
          className="dashboard-user-wrapper"
          ref={userMenuRef}
        >
          {isUserMenuOpen && (
            <div className="dashboard-user-menu">
              <button
                type="button"
                className="dashboard-user-logout"
                onClick={handleLogout}
                disabled={signingOut}
              >
                <FiLogOut />

                <span>
                  {signingOut
                    ? t(
                        "sidebar.loggingOut"
                      )
                    : t(
                        "sidebar.logout"
                      )}
                </span>
              </button>
            </div>
          )}

          <button
            type="button"
            className={`dashboard-user ${
              isUserMenuOpen
                ? "menu-open"
                : ""
            }`}
            onClick={() =>
              setIsUserMenuOpen(
                (current) =>
                  !current
              )
            }
            aria-label={
              t("sidebar.openUserMenu")
            }
            aria-expanded={
              isUserMenuOpen
            }
            disabled={signingOut}
          >
            <div className="dashboard-avatar">
              {profile?.avatar_url ? (
                <img
                  src={
                    profile.avatar_url
                  }
                  alt={
                    profile.full_name ||
                    t("sidebar.profile")
                  }
                />
              ) : (
                profile?.full_name
                  ?.trim()
                  ?.charAt(0)
                  ?.toUpperCase() ||
                "U"
              )}
            </div>

            <div className="dashboard-user-info">
              <strong>
                {profile?.full_name ||
                  t("sidebar.user")}
              </strong>

              <small className="dashboard-user-role">
                {profile?.roles?.name ||
                  t("sidebar.noRole")}
              </small>

              <small className="dashboard-user-username">
                {profile?.username
                  ? `username:${profile.username}`
                  : "@username"}
              </small>
            </div>

            <FiChevronDown
              className={`user-arrow ${
                isUserMenuOpen
                  ? "open"
                  : ""
              }`}
            />
          </button>
        </div>
      </aside>
    </>
  );
}

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";

import { supabase } from "../lib/supabase";

const AuthContext = createContext(null);

const normalizeKey = (value) =>
  String(value || "")
    .trim()
    .toLowerCase();

const normalizePermissions = (
  permissionRows = []
) => {
  return permissionRows.reduce(
    (permissions, row) => {
      const moduleName =
        row.module_name;

      if (!moduleName) {
        return permissions;
      }

      permissions[
        normalizeKey(moduleName)
      ] = {
        view: Boolean(row.can_view),
        add: Boolean(row.can_add),
        edit: Boolean(row.can_edit),
        delete: Boolean(
          row.can_delete
        ),
      };

      return permissions;
    },
    {}
  );
};

export const AuthProvider = ({
  children,
}) => {
  const [user, setUser] =
    useState(null);

  const [session, setSession] =
    useState(null);

  const [profile, setProfile] =
    useState(null);

  const [loading, setLoading] =
    useState(true);

  const getProfile = useCallback(
    async (userId) => {
      if (!userId) {
        setProfile(null);
        return null;
      }

      const { data, error } =
        await supabase
          .from("profiles")
          .select(`
            id,
            full_name,
            username,
            email,
            avatar_url,
            is_active,
            role_id,
            roles (
              id,
              name,
              description,
              is_system_admin,
              role_permissions (
                id,
                module_name,
                can_view,
                can_add,
                can_edit,
                can_delete
              )
            )
          `)
          .eq("id", userId)
          .single();

      if (error) {
        console.error(
          "Profile error:",
          error
        );

        setProfile(null);
        return null;
      }

      const normalizedProfile = {
        ...data,

        permissions:
          normalizePermissions(
            data.roles
              ?.role_permissions || []
          ),
      };

      setProfile(
        normalizedProfile
      );

      return normalizedProfile;
    },
    []
  );

  useEffect(() => {
    let isMounted = true;

    const loadSession = async () => {
      try {
        const { data, error } =
          await supabase.auth
            .getSession();

        if (error) {
          throw error;
        }

        if (!isMounted) {
          return;
        }

        const currentSession =
          data.session;

        setSession(
          currentSession
        );

        setUser(
          currentSession?.user ??
            null
        );

        if (
          currentSession?.user
        ) {
          await getProfile(
            currentSession.user.id
          );
        } else {
          setProfile(null);
        }
      } catch (error) {
        console.error(
          "Session error:",
          error
        );

        if (isMounted) {
          setSession(null);
          setUser(null);
          setProfile(null);
        }
      } finally {
        if (isMounted) {
          setLoading(false);
        }
      }
    };

    loadSession();

    const {
      data: {
        subscription,
      },
    } = supabase.auth
      .onAuthStateChange(
        async (
          event,
          currentSession
        ) => {
          if (!isMounted) {
            return;
          }

          setSession(
            currentSession
          );

          setUser(
            currentSession?.user ??
              null
          );

          if (
            event ===
              "SIGNED_OUT" ||
            !currentSession?.user
          ) {
            setProfile(null);
            setLoading(false);
            return;
          }

          await getProfile(
            currentSession.user.id
          );

          setLoading(false);
        }
      );

    return () => {
      isMounted = false;

      subscription.unsubscribe();
    };
  }, [getProfile]);

  const signOut = async () => {
    const { error } =
      await supabase.auth
        .signOut();

    if (error) {
      console.error(
        "Sign out error:",
        error
      );

      return {
        success: false,
        error,
      };
    }

    localStorage.removeItem(
      "bitesUserProfile"
    );

    setSession(null);
    setUser(null);
    setProfile(null);

    return {
      success: true,
      error: null,
    };
  };

  const refreshProfile =
    useCallback(async () => {
      if (!user?.id) {
        return null;
      }

      return getProfile(
        user.id
      );
    }, [
      user?.id,
      getProfile,
    ]);

  const updateProfileAvatar =
    async (avatarUrl) => {
      if (!user?.id) {
        return {
          success: false,

          error: new Error(
            "No authenticated user."
          ),
        };
      }

      const { error } =
        await supabase
          .from("profiles")
          .update({
            avatar_url:
              avatarUrl,
          })
          .eq("id", user.id);

      if (error) {
        console.error(
          "Avatar update error:",
          error
        );

        return {
          success: false,
          error,
        };
      }

      const updatedProfile =
        await getProfile(
          user.id
        );

      return {
        success: true,
        error: null,
        profile:
          updatedProfile,
      };
    };

  const isAdmin = Boolean(
    profile?.roles
      ?.is_system_admin
  );

  const hasPermission =
    useCallback(
      (
        moduleName,
        action = "view"
      ) => {
        if (isAdmin) {
          return true;
        }

        const moduleKey =
          normalizeKey(
            moduleName
          );

        const actionKey =
          normalizeKey(
            action
          );

        if (
          !moduleKey ||
          !actionKey
        ) {
          return false;
        }

        return Boolean(
          profile?.permissions?.[
            moduleKey
          ]?.[actionKey]
        );
      },
      [
        isAdmin,
        profile?.permissions,
      ]
    );

  const hasAnyPermission =
    useCallback(
      (
        moduleNames = [],
        action = "view"
      ) => {
        if (isAdmin) {
          return true;
        }

        return moduleNames.some(
          (moduleName) =>
            hasPermission(
              moduleName,
              action
            )
        );
      },
      [
        isAdmin,
        hasPermission,
      ]
    );

  const value = useMemo(
    () => ({
      user,
      session,
      profile,
      loading,

      isAuthenticated:
        Boolean(user),

      isAdmin,
      hasPermission,
      hasAnyPermission,
      signOut,
      refreshProfile,
      updateProfileAvatar,
    }),
    [
      user,
      session,
      profile,
      loading,
      isAdmin,
      hasPermission,
      hasAnyPermission,
      refreshProfile,
    ]
  );

  return (
    <AuthContext.Provider
      value={value}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context =
    useContext(AuthContext);

  if (!context) {
    throw new Error(
      "useAuth must be used inside AuthProvider."
    );
  }

  return context;
};

import {
  createContext,
  useCallback,
  useContext,
  useRef,
  useState,
} from "react";

import AppDialog from "../components/common/AppDialog";

const DialogContext = createContext(null);

export function DialogProvider({
  children,
}) {
  const [dialog, setDialog] =
    useState(null);

  const resolverRef = useRef(null);

  const closeDialog = useCallback(
    (result) => {
      resolverRef.current?.(result);
      resolverRef.current = null;
      setDialog(null);
    },
    []
  );

  const showAlert = useCallback(
    ({
      title = "Notice",
      message = "",
      type = "info",
      confirmText = "OK",
    }) =>
      new Promise((resolve) => {
        resolverRef.current = resolve;

        setDialog({
          mode: "alert",
          title,
          message,
          type,
          confirmText,
        });
      }),
    []
  );

  const showConfirm = useCallback(
    ({
      title = "Confirm Action",
      message = "",
      type = "warning",
      confirmText = "Confirm",
      cancelText = "Cancel",
    }) =>
      new Promise((resolve) => {
        resolverRef.current = resolve;

        setDialog({
          mode: "confirm",
          title,
          message,
          type,
          confirmText,
          cancelText,
        });
      }),
    []
  );

  return (
    <DialogContext.Provider
      value={{
        showAlert,
        showConfirm,
      }}
    >
      {children}

      <AppDialog
        open={Boolean(dialog)}
        {...dialog}
        onConfirm={() =>
          closeDialog(true)
        }
        onCancel={() =>
          closeDialog(false)
        }
      />
    </DialogContext.Provider>
  );
}

export function useDialog() {
  const context =
    useContext(DialogContext);

  if (!context) {
    throw new Error(
      "useDialog must be used inside DialogProvider."
    );
  }

  return context;
}

