    setEvents((currentEvents) =>
      currentEvents.filter((event) => event.id !== eventId)
    );
  };

  const value = useMemo(() => ({
    events,
    addEvent,
    updateEvent,
    deleteEvent,
    setEvents,
  }), [events]);

  return (
