import {
  useEffect,
  useMemo,
  useState,
} from "react";

import "../styles/mobile-sidebar-offcanvas.css";
import { useAuth } from "../context/AuthContext";
import { useTranslation } from "react-i18next";


import { useDialog } from "../context/DialogContext";
import Sidebar from "../components/dashboard/Sidebar";
import Topbar from "../components/dashboard/Topbar";

import {
  createPurchase,
  getPurchasePageData,
  receivePurchase,
  removePurchase,
  updatePurchase,
  updatePurchaseStatus,
} from "../services/purchaseService";

import "../styles/dashboard.css";
import "../styles/Purchase.css";

import {
  FiBox,
  FiClock,
  FiDollarSign,
  FiCheckCircle,
  FiPlus,
  FiSearch,
  FiCalendar,
  FiEdit2,
  FiMoreVertical,
  FiX,
  FiCheck,
  FiDownload,
  FiTrash2,
} from "react-icons/fi";

const getTodayDate = () =>
  new Date().toISOString().split("T")[0];

const createEmptyPurchaseItem = () => ({
  itemId: "",
  quantity: "",
  unitCost: "",
});

const createEmptyForm = () => ({
  supplierId: "",
  orderDate: getTodayDate(),
  expectedDate: "",
  warehouseId: "",
  items: [createEmptyPurchaseItem()],
});

export default function Purchase() {
  const { t, i18n } = useTranslation();
  const { showAlert, showConfirm } = useDialog();


  const { hasPermission } = useAuth();

  const canAdd = hasPermission("Purchase", "add");
  const canEdit = hasPermission("Purchase", "edit");
  const canDelete = hasPermission("Purchase", "delete");

  const [purchases, setPurchases] =
    useState([]);

  const [suppliers, setSuppliers] =
    useState([]);

  const [warehouses, setWarehouses] =
    useState([]);

  const [items, setItems] =
    useState([]);

  const [loading, setLoading] =
    useState(true);

  const [saving, setSaving] =
    useState(false);

  const [searchValue, setSearchValue] =
    useState("");

  const [
    selectedWarehouse,
    setSelectedWarehouse,
  ] = useState("All Warehouses");

  const [
    selectedStatus,
    setSelectedStatus,
  ] = useState("All Statuses");

  const [
    showPurchaseModal,
    setShowPurchaseModal,
  ] = useState(false);

  const [
    showReceiveModal,
    setShowReceiveModal,
  ] = useState(false);

  const [formData, setFormData] =
    useState(createEmptyForm());

  const [
    editingPurchaseId,
    setEditingPurchaseId,
  ] = useState(null);

  const [
    receivingPurchase,
    setReceivingPurchase,
  ] = useState(null);

  const [
    openActionId,
    setOpenActionId,
  ] = useState(null);

  const [actionMenuPosition, setActionMenuPosition] =
    useState({
      top: 0,
      left: 0,
    });

  const [currentPage, setCurrentPage] =
    useState(1);

  const purchasesPerPage = 5;

  useEffect(() => {
    loadPurchaseData();
  }, []);

  useEffect(() => {
    if (openActionId === null) {
      return undefined;
    }

    const closeActionMenu = (event) => {
      if (
        event?.target instanceof Element &&
        event.target.closest(".purchase-more-wrapper")
      ) {
        return;
      }

      setOpenActionId(null);
    };

    const closeOnPageMove = () => {
      setOpenActionId(null);
    };

    document.addEventListener("mousedown", closeActionMenu);
    window.addEventListener("scroll", closeOnPageMove, true);
    window.addEventListener("resize", closeOnPageMove);

    return () => {
      document.removeEventListener("mousedown", closeActionMenu);
      window.removeEventListener("scroll", closeOnPageMove, true);
      window.removeEventListener("resize", closeOnPageMove);
    };
  }, [openActionId]);

  const loadPurchaseData = async () => {
    try {
      setLoading(true);

      const data =
        await getPurchasePageData();

      setPurchases(data.purchases);
      setSuppliers(data.suppliers);
      setWarehouses(data.warehouses);
      setItems(data.items);
    } catch (error) {
      console.error(
        "Error loading purchases:",
        error
      );

      showAlert({
        message: error.message ||
          t("purchase.errors.couldNotLoad"),
      });
    } finally {
      setLoading(false);
    }
  };

  const filteredPurchases = useMemo(() => {
    const normalizedSearch =
      searchValue.trim().toLowerCase();

    return purchases.filter((purchase) => {
      const matchesSearch =
        normalizedSearch === "" ||
        [
          purchase.poNumber,
          purchase.supplier,
          purchase.itemNames?.join(" "),
          purchase.orderDate,
          purchase.expectedDate,
          purchase.warehouse,
          purchase.warehouseBranch,
          purchase.status,
        ].some((value) =>
          String(value || "")
            .toLowerCase()
            .includes(normalizedSearch)
        );

      const matchesWarehouse =
        selectedWarehouse ===
          "All Warehouses" ||
        String(purchase.warehouseId) ===
          String(selectedWarehouse);

      const matchesStatus =
        selectedStatus ===
          "All Statuses" ||
        purchase.status === selectedStatus;

      return (
        matchesSearch &&
        matchesWarehouse &&
        matchesStatus
      );
    });
  }, [
    purchases,
    searchValue,
    selectedWarehouse,
    selectedStatus,
  ]);

  const totalPages = Math.max(
    1,
    Math.ceil(
      filteredPurchases.length /
        purchasesPerPage
    )
  );

  const paginatedPurchases = useMemo(() => {
    const startIndex =
      (currentPage - 1) *
      purchasesPerPage;

    return filteredPurchases.slice(
      startIndex,
      startIndex + purchasesPerPage
    );
  }, [
    filteredPurchases,
    currentPage,
  ]);

  useEffect(() => {
    setCurrentPage(1);
    setOpenActionId(null);
  }, [
    searchValue,
    selectedWarehouse,
    selectedStatus,
  ]);

  useEffect(() => {
    if (currentPage > totalPages) {
      setCurrentPage(totalPages);
    }
  }, [currentPage, totalPages]);

  const totalSpent = useMemo(
    () =>
      purchases
        .filter(
          (purchase) =>
            purchase.status ===
            "Received"
        )
        .reduce(
          (total, purchase) =>
            total +
            Number(
              purchase.totalAmount
            ),
          0
        ),
    [purchases]
  );

  const pendingOrders =
    purchases.filter(
      (purchase) =>
        purchase.status === "Pending"
    ).length;

  const receivedItems = purchases
    .filter(
      (purchase) =>
        purchase.status === "Received"
    )
    .reduce(
      (total, purchase) =>
        total +
        Number(purchase.totalQuantity || 0),
      0
    );

  const handleFormChange = (event) => {
    const {
      name,
      value,
    } = event.target;

    setFormData((currentData) => ({
      ...currentData,
      [name]: value,
    }));
  };

  const handlePurchaseItemChange = (
    itemIndex,
    field,
    value
  ) => {
    setFormData((currentData) => ({
      ...currentData,
      items: currentData.items.map(
        (purchaseItem, index) => {
          if (index !== itemIndex) {
            return purchaseItem;
          }

          if (field === "itemId") {
            const selectedItem = items.find(
              (item) =>
                String(item.id) ===
                String(value)
            );

            return {
              ...purchaseItem,
              itemId: value,
              unitCost:
                selectedItem?.purchase_cost ??
                purchaseItem.unitCost,
            };
          }

          return {
            ...purchaseItem,
            [field]: value,
          };
        }
      ),
    }));
  };

  const addPurchaseItem = () => {
    setFormData((currentData) => ({
      ...currentData,
      items: [
        ...currentData.items,
        createEmptyPurchaseItem(),
      ],
    }));
  };

  const removePurchaseItem = (
    itemIndex
  ) => {
    setFormData((currentData) => {
      if (currentData.items.length === 1) {
        return currentData;
      }

      return {
        ...currentData,
        items: currentData.items.filter(
          (_, index) => index !== itemIndex
        ),
      };
    });
  };

  const openNewPurchaseModal = async () => {
    if (!canAdd) {
      await showAlert({
        title: t("purchase.errors.permissionDenied"),
        message:
          t("purchase.errors.noAddPermission"),
        type: "warning",
      });

      return;
    }

    setEditingPurchaseId(null);
    setFormData(createEmptyForm());
    setOpenActionId(null);
    setShowPurchaseModal(true);
  };

  const openEditPurchaseModal = (
    purchase
  ) => {
    if (!canEdit) {
      showAlert({
        message: t("purchase.errors.noEditPermission"),
      });
      return;
    }

    setEditingPurchaseId(purchase.id);

    setFormData({
      supplierId: String(
        purchase.supplierId
      ),
      orderDate: purchase.orderDate,
      expectedDate:
        purchase.expectedDate,
      warehouseId: String(
        purchase.warehouseId
      ),
      items:
        purchase.items?.length > 0
          ? purchase.items.map(
              (purchaseItem) => ({
                itemId: String(
                  purchaseItem.itemId
                ),
                quantity:
                  purchaseItem.quantity,
                unitCost:
                  purchaseItem.unitCost,
              })
            )
          : [createEmptyPurchaseItem()],
    });

    setOpenActionId(null);
    setShowPurchaseModal(true);
  };

  const closePurchaseModal = () => {
    if (saving) {
      return;
    }

    setShowPurchaseModal(false);
    setEditingPurchaseId(null);
    setFormData(createEmptyForm());
  };

  const validatePurchaseForm = () => {
    const requiredFields = [
      "supplierId",
      "orderDate",
      "expectedDate",
      "warehouseId",
    ];

    const hasEmptyField =
      requiredFields.some(
        (field) =>
          String(
            formData[field] || ""
          ).trim() === ""
      );

    if (hasEmptyField) {
      showAlert({
        message:
          t("purchase.errors.completeAllFields"),
      });

      return false;
    }

    if (
      !Array.isArray(formData.items) ||
      formData.items.length === 0
    ) {
      showAlert({
        message:
          t("purchase.errors.addAtLeastOneItem"),
      });

      return false;
    }

    const hasInvalidItem =
      formData.items.some(
        (purchaseItem) =>
          String(
            purchaseItem.itemId || ""
          ).trim() === "" ||
          String(
            purchaseItem.quantity || ""
          ).trim() === "" ||
          String(
            purchaseItem.unitCost ?? ""
          ).trim() === "" ||
          Number(
            purchaseItem.quantity
          ) <= 0 ||
          Number(
            purchaseItem.unitCost
          ) < 0
      );

    if (hasInvalidItem) {
      showAlert({
        message:
          t("purchase.errors.invalidItem"),
      });

      return false;
    }

    const uniqueItemIds = new Set(
      formData.items.map(
        (purchaseItem) =>
          String(purchaseItem.itemId)
      )
    );

    if (
      uniqueItemIds.size !==
      formData.items.length
    ) {
      showAlert({
        message:
          t("purchase.errors.duplicateItem"),
      });

      return false;
    }

    if (
      formData.expectedDate <
      formData.orderDate
    ) {
      showAlert({
        message:
          t("purchase.errors.expectedDateBeforeOrder"),
      });

      return false;
    }

    return true;
  };

  const handleSavePurchase = async (
    event
  ) => {
    event.preventDefault();

    const requiredPermission =
      editingPurchaseId
        ? canEdit
        : canAdd;

    if (!requiredPermission) {
      await showAlert({
        title: t("purchase.errors.permissionDenied"),
        message: editingPurchaseId
          ? t("purchase.errors.noEditPermission")
          : t("purchase.errors.noAddPermission"),
        type: "warning",
      });

      return;
    }

    if (!validatePurchaseForm()) {
      return;
    }

    try {
      setSaving(true);

      if (editingPurchaseId) {
        const updatedPurchase =
          await updatePurchase(
            editingPurchaseId,
            formData
          );

        setPurchases(
          (currentPurchases) =>
            currentPurchases.map(
              (purchase) =>
                purchase.id ===
                editingPurchaseId
                  ? updatedPurchase
                  : purchase
            )
        );
      } else {
        const newPurchase =
          await createPurchase(formData);

        setPurchases(
          (currentPurchases) => [
            newPurchase,
            ...currentPurchases,
          ]
        );
      }

      setShowPurchaseModal(false);
      setEditingPurchaseId(null);
      setFormData(createEmptyForm());
    } catch (error) {
      console.error(
        "Error saving purchase:",
        error
      );

      showAlert({
        message: error.message ||
          t("purchase.errors.couldNotSave"),
      });
    } finally {
      setSaving(false);
    }
  };

  const handleApprovePurchase = async (
    purchaseId
  ) => {
    if (!canEdit) {
      await showAlert({
        title: t("purchase.errors.permissionDenied"),
        message:
          t("purchase.errors.noApprovePermission"),
        type: "warning",
      });

      return;
    }

    try {
      const updatedPurchase =
        await updatePurchaseStatus(
          purchaseId,
          "Approved"
        );

      setPurchases(
        (currentPurchases) =>
          currentPurchases.map(
            (purchase) =>
              purchase.id === purchaseId
                ? updatedPurchase
                : purchase
          )
      );

      setOpenActionId(null);
    } catch (error) {
      showAlert({
        message: error.message ||
          t("purchase.errors.couldNotApprove"),
      });
    }
  };

  const openReceiveModal = async (purchase) => {
    if (!canEdit) {
      await showAlert({
        title: t("purchase.errors.permissionDenied"),
        message:
          t("purchase.errors.noReceivePermission"),
        type: "warning",
      });

      return;
    }

    setReceivingPurchase(purchase);
    setOpenActionId(null);
    setShowReceiveModal(true);
  };

  const closeReceiveModal = () => {
    if (saving) {
      return;
    }

    setShowReceiveModal(false);
    setReceivingPurchase(null);
  };

  const handleReceivePurchase = async (
    event
  ) => {
    if (!canEdit) {
      showAlert({
        message: t("purchase.errors.noReceivePermission"),
      });
      return;
    }

    event.preventDefault();

    if (!receivingPurchase) {
      return;
    }

    try {
      setSaving(true);

      const updatedPurchase =
        await receivePurchase(
          receivingPurchase
        );

      setPurchases(
        (currentPurchases) =>
          currentPurchases.map(
            (purchase) =>
              purchase.id ===
              receivingPurchase.id
                ? updatedPurchase
                : purchase
          )
      );

      setShowReceiveModal(false);
      setReceivingPurchase(null);
    } catch (error) {
      console.error(
        "Error receiving purchase:",
        error
      );

      showAlert({
        message: error.message ||
          t("purchase.errors.couldNotReceive"),
      });
    } finally {
      setSaving(false);
    }
  };

  const handleCancelPurchase = async (
    purchaseId
  ) => {
    if (!canEdit) {
      await showAlert({
        title: t("purchase.errors.permissionDenied"),
        message:
          t("purchase.errors.noCancelPermission"),
        type: "warning",
      });

      return;
    }

    const confirmed = await showConfirm({
      message: t("purchase.confirm.cancel"),
    });

    if (!confirmed) {
      return;
    }

    updatePurchaseStatus(
      purchaseId,
      "Cancelled"
    )
      .then((updatedPurchase) => {
        setPurchases(
          (currentPurchases) =>
            currentPurchases.map(
              (purchase) =>
                purchase.id ===
                purchaseId
                  ? updatedPurchase
                  : purchase
            )
        );

        setOpenActionId(null);
      })
      .catch((error) => {
        showAlert({
        message: error.message ||
            t("purchase.errors.couldNotCancel"),
      });
      });
  };

  const handleDeletePurchase = async (
    purchaseId
  ) => {
    if (!canDelete) {
      showAlert({
        message: t("purchase.errors.noDeletePermission"),
      });
      return;
    }

    const confirmed = await showConfirm({
      message: t("purchase.confirm.delete"),
    });

    if (!confirmed) {
      return;
    }

    try {
      await removePurchase(purchaseId);

      setPurchases(
        (currentPurchases) =>
          currentPurchases.filter(
            (purchase) =>
              purchase.id !== purchaseId
          )
      );

      setOpenActionId(null);
    } catch (error) {
      showAlert({
        message: error.message ||
          t("purchase.errors.couldNotDelete"),
      });
    }
  };

  const toggleActionMenu = (
    event,
    purchaseId
  ) => {
    event.stopPropagation();

    if (openActionId === purchaseId) {
      setOpenActionId(null);
      return;
    }

    const buttonRect =
      event.currentTarget.getBoundingClientRect();

    const menuWidth = 145;
    const menuHeight = 176;
    const gap = 10;

    const availableSpaceBelow =
      window.innerHeight -
      buttonRect.bottom;

    const top =
      availableSpaceBelow >=
      menuHeight + gap
        ? buttonRect.bottom + gap
        : buttonRect.top -
          menuHeight -
          gap;

    const preferredLeft =
      buttonRect.right -
      menuWidth;

    const left = Math.max(
      12,
      Math.min(
        preferredLeft,
        window.innerWidth -
          menuWidth -
          12
      )
    );

    setActionMenuPosition({
      top: Math.max(12, top),
      left,
    });

    setOpenActionId(purchaseId);
  };

  const getStatusClass = (status) =>
    status
      .toLowerCase()
      .replace(/\s+/g, "-");


  const getStatusLabel = (status) =>
    t(
      `purchase.statuses.${String(status || "")
        .trim()
        .toLowerCase()}`,
      {
        defaultValue: status,
      }
    );

  const getWarehouseLabel = (warehouseName) =>
    t(
      `warehouses.${String(warehouseName || "")
        .trim()
        .toLowerCase()
        .replace(/\s+/g, "_")}`,
      {
        defaultValue: warehouseName,
      }
    );

  const formatDate = (dateValue) => {
    if (!dateValue) {
      return "-";
    }

    return new Date(
      `${dateValue}T00:00:00`
    ).toLocaleDateString(
      i18n.language === "ar"
        ? "ar-EG"
        : "en-GB",
      {
      day: "2-digit",
      month: "short",
      year: "numeric",
    });
  };

  return (
    <div className="dashboard-page">
      <Sidebar activePage="purchase" />

      <main className="purchase-main">
        <Topbar
          searchValue={searchValue}
          onSearchChange={setSearchValue}
        />

        <section className="purchase-title-section">
          <div>
            <h1>{t("purchase.title")}</h1>

            <p>{t("purchase.subtitle")}</p>
          </div>

          <button
            type="button"
            className="new-purchase-button"
            onClick={openNewPurchaseModal}
          >
            <FiPlus />
            <span>
              {t("purchase.newRequest")}
            </span>
          </button>
        </section>

        <section className="purchase-stats">
          <PurchaseStatCard
            icon={<FiBox />}
            title={t("purchase.stats.totalOrders")}
            value={purchases.length}
            subtitle={t("purchase.stats.allOrders")}
          />

          <PurchaseStatCard
            icon={<FiClock />}
            title={t("purchase.stats.pendingApproval")}
            value={pendingOrders}
            subtitle={t("purchase.stats.purchaseRequests")}
          />

          <PurchaseStatCard
            icon={<FiCheckCircle />}
            title={t("purchase.stats.itemsReceived")}
            value={receivedItems.toLocaleString()}
            subtitle={t("purchase.stats.inventoryUpdated")}
          />

          <PurchaseStatCard
            icon={<FiDollarSign />}
            title={t("purchase.stats.totalSpent")}
            value={totalSpent.toLocaleString()}
            subtitle={t("purchase.stats.egpReceivedOrders")}
          />
        </section>

        <section className="purchase-filters">
          <div className="purchase-search-box">
            <FiSearch />

            <input
              type="text"
              placeholder={t("purchase.search")}
              value={searchValue}
              onChange={(event) =>
                setSearchValue(
                  event.target.value
                )
              }
            />
          </div>

          <select
            value={selectedWarehouse}
            onChange={(event) =>
              setSelectedWarehouse(
                event.target.value
              )
            }
          >
            <option value="All Warehouses">{t("purchase.allWarehouses")}</option>

            {warehouses.map(
              (warehouse) => (
                <option
                  key={warehouse.id}
                  value={warehouse.id}
                >
                  {getWarehouseLabel(warehouse.name)}
                </option>
              )
            )}
          </select>

          <select
            value={selectedStatus}
            onChange={(event) =>
              setSelectedStatus(
                event.target.value
              )
            }
          >
            <option value="All Statuses">{t("purchase.allStatuses")}</option>

            <option value="Pending">{t("purchase.statuses.pending")}</option>

            <option value="Approved">{t("purchase.statuses.approved")}</option>

            <option value="Received">{t("purchase.statuses.received")}</option>

            <option value="Cancelled">{t("purchase.statuses.cancelled")}</option>
          </select>
        </section>

        <section className="purchase-table-card">
          <div className="purchase-table-wrapper">
            <table>
              <thead>
                <tr>

                  <th>{t("purchase.table.poNumber")}</th>
                  <th>{t("purchase.table.supplier")}</th>
                  <th>{t("purchase.table.orderDate")}</th>
                  <th>{t("purchase.table.expectedDate")}</th>
                  <th>{t("purchase.table.warehouse")}</th>
                  <th>{t("purchase.table.items")}</th>
                  <th>{t("purchase.table.totalQuantity")}</th>
                  <th>{t("purchase.table.totalAmount")}</th>
                  <th>{t("purchase.table.status")}</th>
                  <th>{t("purchase.table.actions")}</th>
                </tr>
              </thead>

              <tbody>
                {loading ? (
                  <tr>
                    <td
                      colSpan="10"
                      className="purchase-empty-state"
                    >
                      {t("purchase.loading")}
                    </td>
                  </tr>
                ) : filteredPurchases.length >
                  0 ? (
                  paginatedPurchases.map(
                    (purchase) => (
                      <tr key={purchase.id}>

                        <td>
                          {purchase.poNumber}
                        </td>

                        <td>
                          {purchase.supplier}
                        </td>

                        <td>
                          <div className="purchase-date-cell">
                            <FiCalendar />

                            <span>
                              {formatDate(
                                purchase.orderDate
                              )}
                            </span>
                          </div>
                        </td>

                        <td>
                          {formatDate(
                            purchase.expectedDate
                          )}
                        </td>

                        <td>
                          {getWarehouseLabel(purchase.warehouse)}
                        </td>

                        <td>
                          <div className="purchase-items-cell">
                            {purchase.itemNames?.length
                              ? purchase.itemNames.join(", ")
                              : "-"}
                          </div>
                        </td>

                        <td>
                          {Number(
                            purchase.totalQuantity
                          ).toLocaleString()}
                        </td>

                        <td>
                          {Number(
                            purchase.totalAmount
                          ).toLocaleString()}{" "}
                          EGP
                        </td>

                        <td>
                          <span
                            className={`purchase-status ${getStatusClass(
                              purchase.status
                            )}`}
                          >
                            {getStatusLabel(purchase.status)}
                          </span>
                        </td>

                        <td>
                          <div className="purchase-actions">
                            <button
                              type="button"
                              aria-label={t("purchase.aria.editOrder", { number: purchase.poNumber })}
                              disabled={
                                purchase.status ===
                                  "Received" ||
                                purchase.status ===
                                  "Cancelled"
                              }
                              onClick={() =>
                                openEditPurchaseModal(
                                  purchase
                                )
                              }
                            >
                              <FiEdit2 />
                            </button>

                            <div className="purchase-more-wrapper">
                              <button
                                type="button"
                                className="purchase-more-button"
                                aria-label={t("purchase.aria.moreActions", { number: purchase.poNumber })}
                                onClick={(event) =>
                                  toggleActionMenu(
                                    event,
                                    purchase.id
                                  )
                                }
                              >
                                <FiMoreVertical />
                              </button>

                              {openActionId ===
                                purchase.id && (
                                <div
                                  className="purchase-action-menu"
                                  style={{
                                    top: `${actionMenuPosition.top}px`,
                                    left: `${actionMenuPosition.left}px`,
                                  }}
                                >
                                  {purchase.status ===
                                    "Pending" && (
                                    <button
                                      type="button"
                                      onClick={() =>
                                        handleApprovePurchase(
                                          purchase.id
                                        )
                                      }
                                    >
                                      <FiCheck />
                                      {t("purchase.actions.approve")}
                                    </button>
                                  )}

                                  {purchase.status ===
                                    "Approved" && (
                                    <button
                                      type="button"
                                      onClick={() =>
                                        openReceiveModal(
                                          purchase
                                        )
                                      }
                                    >
                                      <FiDownload />
                                      {t("purchase.actions.receiveItems")}
                                    </button>
                                  )}

                                  {(purchase.status ===
                                    "Pending" ||
                                    purchase.status ===
                                      "Approved") && (
                                    <button
                                      type="button"
                                      onClick={() =>
                                        openEditPurchaseModal(
                                          purchase
                                        )
                                      }
                                    >
                                      <FiEdit2 />
                                      {t("purchase.actions.edit")}
                                    </button>
                                  )}

                                  {purchase.status !==
                                    "Received" &&
                                    purchase.status !==
                                      "Cancelled" && (
                                      <button
                                        type="button"
                                        className="cancel-action"
                                        onClick={() =>
                                          handleCancelPurchase(
                                            purchase.id
                                          )
                                        }
                                      >
                                        <FiX />
                                        {t("purchase.actions.cancel")}
                                      </button>
                                    )}

                                  <button
                                    type="button"
                                    className="delete-action"
                                    onClick={() =>
                                      handleDeletePurchase(
                                        purchase.id
                                      )
                                    }
                                  >
                                    <FiTrash2 />
                                    {t("purchase.actions.delete")}
                                  </button>
                                </div>
                              )}
                            </div>
                          </div>
                        </td>
                      </tr>
                    )
                  )
                ) : (
                  <tr>
                    <td
                      colSpan="10"
                      className="purchase-empty-state"
                    >
                      No purchase orders match
                      your search.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>

          <div className="purchase-pagination">
            <p>
              {t("purchase.showingOrders", {
                from:
                  filteredPurchases.length === 0
                    ? 0
                    : (currentPage - 1) *
                        purchasesPerPage +
                      1,
                to: Math.min(
                  currentPage *
                    purchasesPerPage,
                  filteredPurchases.length
                ),
                total: filteredPurchases.length,
              })}
            </p>

            <div>
              <button
                type="button"
                onClick={() =>
                  setCurrentPage((page) =>
                    Math.max(1, page - 1)
                  )
                }
                disabled={currentPage === 1}
              >
                 ‹
              </button>

              {Array.from(
                { length: totalPages },
                (_, index) => index + 1
              ).map((pageNumber) => (
                <button
                  key={pageNumber}
                  type="button"
                  className={
                    currentPage === pageNumber
                      ? "active"
                      : ""
                  }
                  onClick={() =>
                    setCurrentPage(pageNumber)
                  }
                >
                  {pageNumber}
                </button>
              ))}

              <button
                type="button"
                onClick={() =>
                  setCurrentPage((page) =>
                    Math.min(
                      totalPages,
                      page + 1
                    )
                  )
                }
                disabled={
                  currentPage === totalPages
                }
              >
                 ›
              </button>
            </div>
          </div>
        </section>
      </main>

      {showPurchaseModal && (
        <div
          className="purchase-modal-overlay"
          onMouseDown={
            closePurchaseModal
          }
        >
          <form
            className="purchase-modal"
            onSubmit={handleSavePurchase}
            onMouseDown={(event) =>
              event.stopPropagation()
            }
          >
            <div className="purchase-modal-header">
              <div>
                <h2>
                  {editingPurchaseId
                    ? t("purchase.modal.editOrder")
                    : t("purchase.newRequest")}
                </h2>

                <p>{t("purchase.modal.enterSupplierInfo")}</p>
              </div>

              <button
                type="button"
                onClick={
                  closePurchaseModal
                }
                aria-label={t("purchase.modal.closeForm")}
                disabled={saving}
              >
                <FiX />
              </button>
            </div>

            <div className="purchase-modal-grid">
              <label>
                {t("purchase.modal.supplier")}

                <select
                  name="supplierId"
                  value={
                    formData.supplierId
                  }
                  onChange={handleFormChange}
                  disabled={saving}
                >
                  <option value="">{t("purchase.modal.selectSupplier")}</option>

                  {suppliers.map(
                    (supplier) => (
                      <option
                        key={supplier.id}
                        value={supplier.id}
                      >
                        {supplier.name}
                      </option>
                    )
                  )}
                </select>
              </label>

              <label>
                {t("purchase.modal.warehouse")}

                <select
                  name="warehouseId"
                  value={
                    formData.warehouseId
                  }
                  onChange={handleFormChange}
                  disabled={saving}
                >
                  <option value="">{t("purchase.modal.selectWarehouse")}</option>

                  {warehouses.map(
                    (warehouse) => (
                      <option
                        key={warehouse.id}
                        value={warehouse.id}
                      >
                        {getWarehouseLabel(warehouse.name)}
                      </option>
                    )
                  )}
                </select>
              </label>

              <label>
                {t("purchase.modal.orderDate")}

                <input
                  type="date"
                  name="orderDate"
                  value={formData.orderDate}
                  onChange={handleFormChange}
                  disabled={saving}
                />
              </label>

              <label>
                {t("purchase.modal.expectedDate")}

                <input
                  type="date"
                  name="expectedDate"
                  value={
                    formData.expectedDate
                  }
                  onChange={handleFormChange}
                  disabled={saving}
                />
              </label>
            </div>

            <section className="purchase-items-section">
              <div className="purchase-items-header">
                <div>
                  <h3>{t("purchase.modal.itemsQuantities")}</h3>
                  <p>
                    {t("purchase.modal.addItemsHelp")}
                  </p>
                </div>

                <button
                  type="button"
                  className="purchase-add-item-button"
                  onClick={addPurchaseItem}
                  disabled={saving}
                >
                  <FiPlus />
                  {t("purchase.modal.addItem")}
                </button>
              </div>

              <div className="purchase-items-list">
                {formData.items.map(
                  (purchaseItem, itemIndex) => (
                    <div
                      key={itemIndex}
                      className="purchase-item-row"
                    >
                      <label>
                        {t("purchase.modal.item")}

                        <select
                          value={
                            purchaseItem.itemId
                          }
                          onChange={(event) =>
                            handlePurchaseItemChange(
                              itemIndex,
                              "itemId",
                              event.target.value
                            )
                          }
                          disabled={saving}
                        >
                          <option value="">
                            {t("purchase.modal.selectItem")}
                          </option>

                          {items.map((item) => (
                            <option
                              key={item.id}
                              value={item.id}
                            >
                              {item.name}
                            </option>
                          ))}
                        </select>
                      </label>

                      <label>
                        {t("purchase.modal.quantity")}

                        <input
                          type="number"
                          min="1"
                          value={
                            purchaseItem.quantity
                          }
                          onChange={(event) =>
                            handlePurchaseItemChange(
                              itemIndex,
                              "quantity",
                              event.target.value
                            )
                          }
                          placeholder="500"
                          disabled={saving}
                        />
                      </label>

                      <label>
                        {t("purchase.modal.unitCost")}

                        <input
                          type="number"
                          min="0"
                          step="0.01"
                          value={
                            purchaseItem.unitCost
                          }
                          onChange={(event) =>
                            handlePurchaseItemChange(
                              itemIndex,
                              "unitCost",
                              event.target.value
                            )
                          }
                          placeholder="0.00"
                          disabled={saving}
                        />
                      </label>

                      <button
                        type="button"
                        className="purchase-remove-item-button"
                        onClick={() =>
                          removePurchaseItem(
                            itemIndex
                          )
                        }
                        disabled={
                          saving ||
                          formData.items.length ===
                            1
                        }
                        aria-label={t("purchase.modal.removeItem")}
                      >
                        <FiTrash2 />
                      </button>
                    </div>
                  )
                )}
              </div>
            </section>

            <div className="purchase-total-preview">
              {t("purchase.modal.estimatedTotal")}

              <strong>
                {formData.items
                  .reduce(
                    (total, purchaseItem) =>
                      total +
                      Number(
                        purchaseItem.quantity ||
                          0
                      ) *
                        Number(
                          purchaseItem.unitCost ||
                            0
                        ),
                    0
                  )
                  .toLocaleString()}{" "}
                EGP
              </strong>
            </div>

            <div className="purchase-modal-actions">
              <button
                type="button"
                className="purchase-cancel-button"
                onClick={
                  closePurchaseModal
                }
                disabled={saving}
              >
                {t("purchase.actions.cancel")}
              </button>

              <button
                type="submit"
                className="purchase-save-button"
                disabled={saving}
              >
                {saving
                  ? "Saving..."
                  : editingPurchaseId
                    ? "Update Order"
                    : t("purchase.modal.createRequest")}
              </button>
            </div>
          </form>
        </div>
      )}

      {showReceiveModal &&
        receivingPurchase && (
        <div
          className="purchase-modal-overlay"
          onMouseDown={
            closeReceiveModal
          }
        >
          <form
            className="purchase-modal receive-modal"
            onSubmit={
              handleReceivePurchase
            }
            onMouseDown={(event) =>
              event.stopPropagation()
            }
          >
            <div className="purchase-modal-header">
              <div>
                <h2>{t("purchase.receive.title")}</h2>

                <p>
                  Confirm received items to update
                  inventory.
                </p>
              </div>

              <button
                type="button"
                onClick={
                  closeReceiveModal
                }
                disabled={saving}
              >
                <FiX />
              </button>
            </div>

            <div className="receive-summary">
              <div>
                <span>{t("purchase.table.poNumber")}</span>

                <strong>
                  {
                    receivingPurchase.poNumber
                  }
                </strong>
              </div>

              <div className="receive-summary-items">
                <span>{t("purchase.table.items")}</span>

                <strong>
                  {receivingPurchase.items
                    .map(
                      (purchaseItem) =>
                        `${purchaseItem.name} (${Number(
                          purchaseItem.quantity
                        ).toLocaleString()})`
                    )
                    .join(", ")}
                </strong>
              </div>

              <div>
                <span>{t("purchase.table.totalQuantity")}</span>

                <strong>
                  {Number(
                    receivingPurchase.totalQuantity
                  ).toLocaleString()}
                </strong>
              </div>

              <div>
                <span>{t("purchase.table.warehouse")}</span>

                <strong>
                  {
                    receivingPurchase.warehouse
                  }
                </strong>
              </div>
            </div>

            <div className="inventory-update-note">
              <FiCheckCircle />

              Inventory will be updated after
              confirming receipt.
            </div>

            <div className="purchase-modal-actions">
              <button
                type="button"
                className="purchase-cancel-button"
                onClick={
                  closeReceiveModal
                }
                disabled={saving}
              >
                {t("purchase.actions.cancel")}
              </button>

              <button
                type="submit"
                className="purchase-save-button"
                disabled={saving}
              >
                {saving
                  ? "Receiving..."
                  : "Receive Items"}
              </button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}

function PurchaseStatCard({
  icon,
  title,
  value,
  subtitle,
}) {
  return (
    <article className="purchase-stat-card">
      <div className="purchase-stat-content">
        <div className="purchase-stat-icon">
          {icon}
        </div>

        <div>
          <h4>{title}</h4>
          <h2>{value}</h2>
          <p>{subtitle}</p>
        </div>
      </div>
    </article>
  );
}

import React, {
  useState,
} from "react";

import {
  Link,
  useNavigate,
} from "react-router-dom";

import {
  FiUser,
  FiMail,
  FiLock,
  FiEye,
  FiEyeOff,
  FiArrowRight,
} from "react-icons/fi";

import {
  supabase,
} from "../lib/supabase";

import Background from "../assets/images/Background2.svg";
import MobileBackground from "../assets/images/registerMobile.svg";

import "../styles/register.css";

const Register = () => {
  const navigate = useNavigate();

  const [
    showPassword,
    setShowPassword,
  ] = useState(false);

  const [
    showConfirmPassword,
    setShowConfirmPassword,
  ] = useState(false);

  const [
    isSubmitting,
    setIsSubmitting,
  ] = useState(false);

  const [
    formError,
    setFormError,
  ] = useState("");

  const [
    successMessage,
    setSuccessMessage,
  ] = useState("");

  const [
    formData,
    setFormData,
  ] = useState({
    fullName: "",
    email: "",
    password: "",
    confirmPassword: "",
  });

  const handleChange = (event) => {
    const {
      name,
      value,
    } = event.target;

    setFormData((previousData) => ({
      ...previousData,
      [name]: value,
    }));

    setFormError("");
    setSuccessMessage("");
  };

  const getPasswordStrength = (
    password
  ) => {
    if (password.length === 0) {
      return 0;
    }

    if (password.length < 6) {
      return 1;
    }

    if (password.length < 10) {
      return 2;
    }

    return 3;
  };

  const strength =
    getPasswordStrength(
      formData.password
    );

  const handleSubmit = async (
    event
  ) => {
    event.preventDefault();

    setFormError("");
    setSuccessMessage("");

    const fullName =
      formData.fullName.trim();

    const email =
      formData.email
        .trim()
        .toLowerCase();

    if (!fullName) {
      setFormError(
        "Please enter your full name."
      );

      return;
    }

    if (
      formData.password.length < 6
    ) {
      setFormError(
        "Password must contain at least 6 characters."
      );

      return;
    }

    if (
      formData.password !==
      formData.confirmPassword
    ) {
      setFormError(
        "Passwords do not match."
      );

      return;
    }

    setIsSubmitting(true);

    try {
      const {
        data,
        error,
      } = await supabase.auth.signUp({
        email,
        password:
          formData.password,

        options: {
          data: {
            full_name: fullName,
          },
        },
      });

      if (error) {
        throw error;
      }

      if (!data.user) {
        throw new Error(
          "The account could not be created."
        );
      }

      setSuccessMessage(
        data.session
          ? "Account created successfully."
          : "Account created. Please check your email to confirm your account."
      );

      setFormData({
        fullName: "",
        email: "",
        password: "",
        confirmPassword: "",
      });

      if (data.session) {
        await supabase.auth.signOut();
      }

      window.setTimeout(() => {
        navigate("/login");
      }, 1800);
    } catch (error) {
      console.error(
        "Registration error:",
        error
      );

      setFormError(
        error.message ||
          "Something went wrong while creating the account."
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="register-page">
      <picture className="register-picture">
        <source
          media="(max-width: 600px)"
          srcSet={MobileBackground}
        />

        <img
          src={Background}
          alt="Bites registration background"
          className="register-background"
        />
      </picture>

      <div className="register-content">
        <div className="register-card">
          <h2>Create Your Account</h2>

          <p className="subtitle">
            Fill in your details to get
            started
          </p>

          <form onSubmit={handleSubmit}>
            <div className="input-group">
              <label htmlFor="fullName">
                Full Name
              </label>

              <div className="input-wrapper">
                <FiUser className="input-icon" />

                <input
                  id="fullName"
                  type="text"
                  name="fullName"
                  placeholder="Enter your full name"
                  value={
                    formData.fullName
                  }
                  onChange={handleChange}
                  autoComplete="name"
                  disabled={isSubmitting}
                  required
                />
              </div>
            </div>

            <div className="input-group">
              <label htmlFor="email">
                Email Address
              </label>

              <div className="input-wrapper">
                <FiMail className="input-icon" />

                <input
                  id="email"
                  type="email"
                  name="email"
                  placeholder="Enter your email address"
                  value={formData.email}
                  onChange={handleChange}
                  autoComplete="email"
                  disabled={isSubmitting}
                  required
                />
              </div>
            </div>

            <div className="input-group">
              <label htmlFor="password">
                Password
              </label>

              <div className="input-wrapper">
                <FiLock className="input-icon" />

                <input
                  id="password"
                  type={
                    showPassword
                      ? "text"
                      : "password"
                  }
                  name="password"
                  placeholder="Enter your password"
                  value={
                    formData.password
                  }
                  onChange={handleChange}
                  autoComplete="new-password"
                  minLength={6}
                  disabled={isSubmitting}
                  required
                />

                <button
                  type="button"
                  className="toggle-icon"
                  onClick={() =>
                    setShowPassword(
                      (previous) =>
                        !previous
                    )
                  }
                  aria-label={
                    showPassword
                      ? "Hide password"
                      : "Show password"
                  }
                  disabled={isSubmitting}
                >
                  {showPassword ? (
                    <FiEyeOff />
                  ) : (
                    <FiEye />
                  )}
                </button>
              </div>

              <div className="password-strength">
                <div className="strength-bar">
                  <span
                    className={
                      strength >= 1
                        ? "active"
                        : ""
                    }
                  />

                  <span
                    className={
                      strength >= 2
                        ? "active"
                        : ""
                    }
                  />

                  <span
                    className={
                      strength >= 3
                        ? "active"
                        : ""
                    }
                  />
                </div>

                <small>
                  Password strength
                </small>
              </div>
            </div>

            <div className="input-group">
              <label htmlFor="confirmPassword">
                Confirm Password
              </label>

              <div className="input-wrapper">
                <FiLock className="input-icon" />

                <input
                  id="confirmPassword"
                  type={
                    showConfirmPassword
                      ? "text"
                      : "password"
                  }
                  name="confirmPassword"
                  placeholder="Confirm your password"
                  value={
                    formData
                      .confirmPassword
                  }
                  onChange={handleChange}
                  autoComplete="new-password"
                  minLength={6}
                  disabled={isSubmitting}
                  required
                />

                <button
                  type="button"
                  className="toggle-icon"
                  onClick={() =>
                    setShowConfirmPassword(
                      (previous) =>
                        !previous
                    )
                  }
                  aria-label={
                    showConfirmPassword
                      ? "Hide confirm password"
                      : "Show confirm password"
                  }
                  disabled={isSubmitting}
                >
                  {showConfirmPassword ? (
                    <FiEyeOff />
                  ) : (
                    <FiEye />
                  )}
                </button>
              </div>
            </div>

            {formError && (
              <p
                className="register-message register-error"
                role="alert"
              >
                {formError}
              </p>
            )}

            {successMessage && (
              <p
                className="register-message register-success"
                role="status"
              >
                {successMessage}
              </p>
            )}

            <button
              type="submit"
              className="create-btn"
              disabled={isSubmitting}
            >
              {isSubmitting
                ? "Creating Account..."
                : "Create Account"}

              {!isSubmitting && (
                <FiArrowRight />
              )}
            </button>

            <div className="divider">
              <span>or</span>
            </div>

            <p className="signin-text">
              Already have an account?

              <Link to="/login">
                Sign In →
              </Link>
            </p>
          </form>
        </div>

        <p className="terms">
          By creating an account, you
          agree to our{" "}

          <a href="#">
            Terms of Service
          </a>

          {" "}and{" "}

          <a href="#">
            Privacy Policy
          </a>
          .
        </p>
      </div>
    </div>
  );
};

export default Register;

