          <form
            className="settings-user-modal"
            onSubmit={handleCreateUser}
            onMouseDown={(event) =>
              event.stopPropagation()
            }
          >
            <div className="settings-role-modal-header">
              <div>
                <h2>{t("settingsPage.userModal.title")}</h2>

                <p>{t("settingsPage.userModal.subtitle")}</p>
              </div>

              <button
                type="button"
                onClick={closeUserModal}
                disabled={saving}
                aria-label="Close"
              >
                <FiX />
              </button>
            </div>

            <div className="settings-user-section">
              <div className="settings-user-section-header">
                <span>1</span>

                <div>
                  <h3>
                    {t("settingsPage.userModal.accountInfo")}
                  </h3>

                  <p>
                    Enter employee login
                    details.
                  </p>
                </div>
              </div>

              <div className="settings-user-grid">
                <label>
                  {t("settingsPage.userModal.fullName")}

                  <input
                    name="fullName"
                    value={
                      userForm.fullName
                    }
                    placeholder={t("settingsPage.userModal.fullNamePlaceholder")}
                    onChange={
                      handleUserFormChange
                    }
                    disabled={saving}
                  />
                </label>

                <label>
                  {t("settingsPage.userModal.username")}

                  <input
                    type="text"
                    name="username"
                    value={
                      userForm.username
                    }
                    placeholder={t("settingsPage.userModal.usernamePlaceholder")}
                    onChange={
                      handleUserFormChange
                    }
                    autoComplete="off"
                    disabled={saving}
                  />
                </label>

                <label>
                   {t("settingsPage.userModal.password")}

                  <input
                    type="password"
                    name="password"
                    value={
                      userForm.password
                    }
                    placeholder={t("settingsPage.userModal.passwordPlaceholder")}
                    onChange={
                      handleUserFormChange
                    }
                    disabled={saving}
                  />
                </label>

                <label>
                  {t("settingsPage.userModal.confirmPassword")}

                  <input
                    type="password"
                    name="confirmPassword"
                    value={
                      userForm.confirmPassword
                    }
                    placeholder={t("settingsPage.userModal.repeatPassword")}
                    onChange={
                      handleUserFormChange
                    }
                    disabled={saving}
                  />
                </label>

                <label>
                  {t("settingsPage.userModal.role")}

                  <select
                    name="roleId"
                    value={
                      userForm.roleId
                    }
                    onChange={
                      handleUserFormChange
                    }
                    disabled={saving}
                  >
                    <option value="">
                      Select role
                    </option>

                    {roles.map(
                      (role) => (
                        <option
                          key={role.id}
                          value={role.id}
                        >
                          {role.name}
                        </option>
                      )
                    )}
                  </select>
                </label>

                <label>
                  {t("settingsPage.userModal.branch")}

                  <select
                    name="branch"
                    value={
                      userForm.branch
                    }
                    onChange={
                      handleUserFormChange
                    }
                    disabled={saving}
                  >
                    <option value="Cairo">
                      Cairo
                    </option>

                    <option value="Alex">
                      Alex
                    </option>
                  </select>
                </label>
              </div>

              <div className="settings-user-note">
                Employees sign in using
                their username and
                temporary password.
                They do not have password
                recovery by email.
              </div>
            </div>

            {isDriverRole && (
              <div className="settings-user-section">
                <div className="settings-user-section-header">
                  <span>2</span>

                  <div>
                    <h3>
                      {t("settingsPage.staff.driverInfo")}
                    </h3>

                    <p>
                      Enter driver,
                      vehicle and document
                      information.
                    </p>
                  </div>
                </div>

                <div className="staff-form-grid">
                  <label>
                    {t("settingsPage.general.phone")} Number

                    <input
                      type="tel"
                      name="phone"
                      value={
                        driverForm.phone
                      }
                      onChange={
                        handleDriverChange
                      }
                      inputMode="numeric"
                      maxLength={11}
                      pattern="01[0-9]{9}"
                      title="Phone number must be 11 digits and start with 01"
