                        driverForm.licenseExpiryDate
                      }
                      onChange={
                        handleDriverChange
                      }
                      disabled={saving}
                    />
                  </label>

                  <label>
                    Car Number

                    <input
                      name="carNumber"
                      value={
                        driverForm.carNumber
                      }
                      onChange={
                        handleDriverChange
                      }
                      disabled={saving}
                    />
                  </label>

                  <label>
                    Car Type

                    <select
                      name="carType"
                      value={
                        driverForm.carType
                      }
                      onChange={
                        handleDriverChange
                      }
                      disabled={saving}
                    >
                      <option value="Van">
                        Van
                      </option>
                      <option value="Truck">
                        Truck
                      </option>
                      <option value="Pickup">
                        Pickup
                      </option>
                      <option value="Refrigerated Truck">
                        Refrigerated Truck
                      </option>
                      <option value="Other">
                        Other
                      </option>
                    </select>
                  </label>

                  <label>
                    Status

                    <select
                      name="status"
                      value={
                        driverForm.status
                      }
                      onChange={
                        handleDriverChange
                      }
                      disabled={saving}
                    >
                      <option value="Active">
                        Active
                      </option>
                      <option value="Inactive">
                        Inactive
                      </option>
                      <option value="Suspended">
                        Suspended
                      </option>
                    </select>
                  </label>

                  <label>
                    Event Rate (EGP)

                    <input
                      type="number"
                      min="0"
                      step="0.01"
                      name="eventRate"
                      value={
                        driverForm.eventRate
                      }
                      onChange={
                        handleDriverChange
                      }
                      disabled={saving}
                    />
                  </label>

                  <label>
                    Driver Role

                    <select
                      name="staffRole"
                      value={
                        driverForm.staffRole
                      }
                      onChange={(event) => {
                        handleDriverChange(
                          event
                        );

                        if (
                          event.target.value ===
                          "Head Driver"
                        ) {
                          setDriverForm(
                            (current) => ({
                              ...current,
                              staffRole:
                                "Head Driver",
                              reportsToId: "",
                            })
                          );
                        }
                      }}
                      disabled={saving}
                    >
                      <option value="Driver">
                        Driver
                      </option>
                      <option value="Head Driver">
                        Head Driver
                      </option>
                    </select>
                  </label>

                  {driverForm.staffRole ===
                    "Driver" && (
                    <label>
                      Reports To

                      <select
                        name="reportsToId"
                        value={
                          driverForm.reportsToId
                        }
                        onChange={
                          handleDriverChange
                        }
                        disabled={saving}
                      >
                        <option value="">
                          No Head Driver
                        </option>

                        {headDrivers.map(
                          (driver) => (
                            <option
                              key={driver.id}
                              value={driver.id}
                            >
                              {
                                driver.fullName
                              }
                            </option>
                          )
                        )}
                      </select>
                    </label>
                  )}
                </div>

                <div className="staff-documents-section">
