                  <div className="staff-upload-grid">
                    <label className="staff-upload-box">
                      <FiImage />

                      <span>
                        National ID Image
                      </span>

                      <small>
                        {driverForm
                          .documents
                          .nationalIdImage
                          ?.name ||
                          "Upload image"}
                      </small>

                      <input
                        type="file"
                        accept="image/*"
                        disabled={saving}
                        onChange={(event) =>
                          setDriverDocument(
                            "nationalIdImage",
                            event.target
                              .files[0]
                          )
                        }
                      />
                    </label>

                    <label className="staff-upload-box">
                      <FiUpload />

                      <span>
                        License Image
                      </span>

                      <small>
                        {driverForm
                          .documents
                          .licenseImage
                          ?.name ||
                          "Upload image"}
                      </small>

                      <input
                        type="file"
                        accept="image/*"
                        disabled={saving}
                        onChange={(event) =>
                          setDriverDocument(
                            "licenseImage",
                            event.target
                              .files[0]
                          )
                        }
                      />
                    </label>
                  </div>
                </div>
              </div>
            )}

