                      type="text"
                      name="nationalId"
                      value={
                        waiterForm.nationalId
                      }
                      onChange={
                        handleWaiterChange
                      }
                      inputMode="numeric"
                      maxLength={14}
                      pattern="[0-9]{14}"
                      title="National ID must contain exactly 14 digits"
