                    <select
                      name="status"
                      value={
                        waiterForm.status
                      }
                      onChange={
                        handleWaiterChange
                      }
                      disabled={saving}
                    >
                      <option value="Active">
                        Active
                      </option>
                      <option value="Inactive">
                        Inactive
                      </option>
                      <option value="Suspended">
                        Suspended
                      </option>
                    </select>
                  </label>

