                    <input
                      type="number"
                      min="0"
                      step="0.01"
                      name="eventRate"
                      value={
                        waiterForm.eventRate
                      }
                      onChange={
                        handleWaiterChange
                      }
                      disabled={saving}
                    />
                  </label>

