                      <FiImage />

                      <span>
                        Personal Photo
                      </span>

                      <small>
                        {waiterForm
                          .documents
                          .personalPhoto
                          ?.name ||
                          "Upload file"}
                      </small>

                      <input
                        type="file"
                        accept="image/*"
                        disabled={saving}
                        onChange={(event) =>
                          setWaiterDocument(
                            "personalPhoto",
                            event.target
                              .files[0]
