                    <label className="staff-upload-box">
                      <FiImage />

                      <span>
                        National ID Image
                      </span>

                      <small>
                        {waiterForm
                          .documents
                          .nationalIdImage
                          ?.name ||
                          "Upload file"}
                      </small>

                      <input
                        type="file"
                        accept="image/*"
                        disabled={saving}
                        onChange={(event) =>
                          setWaiterDocument(
                            "nationalIdImage",
                            event.target
                              .files[0]
                          )
                        }
                      />
                    </label>

                    <label className="staff-upload-box">
                      <FiFileText />

                      <span>
                        Health Certificate
                      </span>

                      <small>
                        {waiterForm
                          .documents
                          .healthCertificate
                          .file?.name ||
                          "Upload file"}
                      </small>

                      <input
                        type="file"
                        disabled={saving}
                        onChange={(event) =>
                          setWaiterDocument(
                            "healthCertificate",
                            event.target
                              .files[0]
