                        }
                      />
                    </label>

                    <label className="staff-upload-box">
                      <FiFileText />

                      <span>
                        Contract
                      </span>

                      <small>
                        {waiterForm
                          .documents
                          .contract.file
                          ?.name ||
                          "Upload file"}
                      </small>

                      <input
                        type="file"
                        disabled={saving}
                        onChange={(event) =>
                          setWaiterDocument(
                            "contract",
                            event.target
                              .files[0]
                          )
                        }
                      />
                    </label>
                  </div>

                  <div className="staff-document-dates">
                    <label>
                      Health Certificate
