                      <input
                        type="date"
                        value={
                          waiterForm
                            .documents
                            .healthCertificate
                            .expiryDate
                        }
                        disabled={saving}
                        onChange={(event) =>
                          setWaiterDate(
                            "healthCertificate",
                            "expiryDate",
                            event.target
                              .value
                          )
                        }
                      />
                    </label>

                    <label>
                      Contract Start Date

                      <input
                        type="date"
                        value={
                          waiterForm
                            .documents
                            .contract
                            .startDate
                        }
                        disabled={saving}
                        onChange={(event) =>
                          setWaiterDate(
                            "contract",
                            "startDate",
                            event.target
                              .value
                          )
                        }
                      />
                    </label>

                    <label>
                      Contract End Date

                      <input
                        type="date"
                        value={
                          waiterForm
                            .documents
                            .contract
                            .endDate
                        }
                        disabled={saving}
                        onChange={(event) =>
                          setWaiterDate(
                            "contract",
                            "endDate",
                            event.target
                              .value
                          )
                        }
                      />
                    </label>
                  </div>
                </div>
              </div>
            )}



            <div className="settings-role-modal-actions">
              <button
                type="button"
                onClick={closeUserModal}
                disabled={saving}
              >
                {t("settingsPage.common.cancel")}
              </button>

              <button
                type="submit"
                className="create-role-button"
                disabled={saving}
              >
                {saving
                  ? "Creating..."
                  : "Create User"}
              </button>
            </div>
          </form>
        </div>
      )}


      {showResetPasswordModal && (
        <div
          className="settings-modal-overlay"
          onMouseDown={
            closeResetPasswordModal
          }
        >
          <form
            className="settings-role-modal reset-password-modal"
            onSubmit={
              handleResetPassword
            }
            onMouseDown={(event) =>
              event.stopPropagation()
            }
          >
            <div className="settings-role-modal-header">
              <div>
                <h2>{t("settingsPage.resetPassword.title")}</h2>
                <p>
                  Create a new password
                  for{" "}
                  {resetPasswordUser?.name ||
                    "this user"}.
                </p>
              </div>

              <button
                type="button"
                onClick={
                  closeResetPasswordModal
                }
                disabled={saving}
              >
                <FiX />
              </button>
            </div>

            <div className="reset-password-user">
              <strong>
                {resetPasswordUser?.name ||
                  "User"}
              </strong>
              <span>
                @{resetPasswordUser?.username ||
                  "username"}
              </span>
            </div>

            <label>
              New Password
              <input
                type="password"
                value={
                  resetPasswordForm.password
                }
                placeholder="Minimum 6 characters"
                disabled={saving}
                onChange={(event) =>
                  setResetPasswordForm(
                    (current) => ({
                      ...current,
                      password:
                        event.target.value,
                    })
                  )
                }
              />
            </label>

            <label>
              Confirm Password
              <input
                type="password"
                value={
                  resetPasswordForm.confirmPassword
                }
                placeholder="Repeat password"
                disabled={saving}
                onChange={(event) =>
                  setResetPasswordForm(
                    (current) => ({
                      ...current,
                      confirmPassword:
                        event.target.value,
                    })
                  )
                }
              />
            </label>

            <div className="settings-role-modal-actions">
              <button
                type="button"
                onClick={
                  closeResetPasswordModal
                }
                disabled={saving}
              >
                {t("settingsPage.common.cancel")}
              </button>

              <button
                type="submit"
                className="create-role-button"
                disabled={saving}
              >
                {saving
                  ? "Resetting..."
                  : "Reset Password"}
              </button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}

