source:
import {
  useEffect,
  useMemo,
  useState,
} from "react";
import { useTranslation } from "react-i18next";

import { useAuth } from "../context/AuthContext";


import { useDialog } from "../context/DialogContext";
import Sidebar from "../components/dashboard/Sidebar";
import Topbar from "../components/dashboard/Topbar";

import {
  deleteStaff,
  getStaff,
  getStaffNationalId,
  updateDriver,
  updateWaiter,
} from "../services/staffService";

import {
  getStaffPayments,
  recordStaffPayment,
} from "../services/staffPaymentService";

import "../styles/dashboard.css";
import "../styles/Staff.css";

import {
  FiUsers,
  FiTruck,
  FiSearch,
  FiEdit2,
  FiTrash2,
  FiMoreVertical,
  FiX,
  FiUpload,
  FiFileText,
  FiImage,
} from "react-icons/fi";

const driverEmptyForm = {
  fullName: "",
  phone: "",
  nationalId: "",
  licenseNumber: "",
  licenseExpiryDate: "",
  carNumber: "",
  carType: "Van",
  status: "Active",
  eventRate: "",
  branch: "",
  staffRole: "Driver",
  reportsToId: "",
  documents: {
    nationalIdImage: null,
    licenseImage: null,
  },
};

const waiterEmptyForm = {
  fullName: "",
  phone: "",
  nationalId: "",
  status: "Active",
  eventRate: "",
  branch: "",
  staffRole: "Waiter",
  reportsToId: "",
  documents: {
    personalPhoto: null,
    nationalIdImage: null,
    healthCertificate: {
      file: null,
      expiryDate: "",
    },
    contract: {
      file: null,
      startDate: "",
      endDate: "",
    },
  },
};

const formatDate = (value) => {
  if (!value) {
    return "-";
  }

  return new Date(
    `${value}T00:00:00`
  ).toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
};

const maskNationalId = (value) => {
  const nationalId = String(value || "");

  if (!nationalId) {
    return "-";
  }

  return `${"*".repeat(
    Math.max(nationalId.length - 4, 0)
  )}${nationalId.slice(-4)}`;
};

export default function Staff() {
  const { t, i18n } = useTranslation();
  const { showAlert, showConfirm } = useDialog();


  const { hasPermission, isAdmin } = useAuth();

  const canEdit = hasPermission("Staff", "edit");
  const canDelete = hasPermission("Staff", "delete");

  const [drivers, setDrivers] =
    useState([]);

  const [waiters, setWaiters] =
    useState([]);

  const [payments, setPayments] =
    useState([]);

  const [
    paymentsLoading,
    setPaymentsLoading,
  ] = useState(true);

  const [
    selectedEventDetails,
    setSelectedEventDetails,
  ] = useState(null);

  const [
    selectedStaffPayment,
    setSelectedStaffPayment,
  ] = useState(null);

  const [paymentDrafts, setPaymentDrafts] =
    useState({});

  const [paymentSavingKey, setPaymentSavingKey] =
    useState(null);

  const [loading, setLoading] =
    useState(true);

  const [saving, setSaving] =
    useState(false);

  const [activeTab, setActiveTab] =
    useState("drivers");

  const [searchValue, setSearchValue] =
    useState("");

  const [statusFilter, setStatusFilter] =
    useState("All Statuses");

  const [
    showDriverModal,
    setShowDriverModal,
  ] = useState(false);

  const [
    showWaiterModal,
    setShowWaiterModal,
  ] = useState(false);

  const [
    editingDriverId,
    setEditingDriverId,
  ] = useState(null);

  const [
    editingWaiterId,
    setEditingWaiterId,
  ] = useState(null);

  const [
    openActionId,
    setOpenActionId,
  ] = useState(null);

  const [
    actionMenuPosition,
    setActionMenuPosition,
  ] = useState({
    top: 0,
    left: 0,
  });

  const [currentPage, setCurrentPage] =
    useState(1);

  const staffPerPage = 5;

  const [driverForm, setDriverForm] =
    useState(driverEmptyForm);

  const [waiterForm, setWaiterForm] =
    useState(waiterEmptyForm);

  useEffect(() => {
    loadStaff();
  }, []);

  useEffect(() => {
    if (openActionId === null) {
      return undefined;
    }

    const closeActionMenu = (event) => {
      if (
        event?.target instanceof Element &&
        event.target.closest(
          ".staff-more-wrapper"
        )
      ) {
        return;
      }

      setOpenActionId(null);
    };

    const closeOnPageMove = () => {
      setOpenActionId(null);
    };

    document.addEventListener(
      "mousedown",
      closeActionMenu
    );

    window.addEventListener(
      "scroll",
      closeOnPageMove,
      true
    );

    window.addEventListener(
      "resize",
      closeOnPageMove
    );

    return () => {
      document.removeEventListener(
        "mousedown",
        closeActionMenu
      );

      window.removeEventListener(
        "scroll",
        closeOnPageMove,
        true
      );

      window.removeEventListener(
        "resize",
        closeOnPageMove
      );
    };
  }, [openActionId]);

  const loadStaff = async () => {
    try {
      setLoading(true);

      const [
        data,
        paymentData,
      ] = await Promise.all([
        getStaff(),
        getStaffPayments(),
      ]);

      setDrivers(data.drivers || []);
      setWaiters(data.waiters || []);
      setPayments(paymentData || []);
      setPaymentsLoading(false);
    } catch (error) {
      console.error(
        "Error loading staff:",
        error
      );

      showAlert({
        message: error.message ||
          t("staffPage.errors.couldNotLoad"),
      });
    } finally {
      setLoading(false);
      setPaymentsLoading(false);
    }
  };

  const filteredDrivers = useMemo(() => {
    const search =
      searchValue.trim().toLowerCase();

    return drivers.filter((driver) => {
      const matchesSearch =
        search === "" ||
        [
          driver.id,
          driver.fullName,
          driver.phone,
          driver.nationalId,
          driver.licenseNumber,
          driver.carNumber,
          driver.carType,
          driver.staffRole,
          driver.reportsToName,
          driver.eventRate,
          driver.status,
        ].some((value) =>
          String(value)
            .toLowerCase()
            .includes(search)
        );

      return (
        matchesSearch &&
        (
          statusFilter ===
            "All Statuses" ||
          driver.status ===
            statusFilter
        )
      );
    });
  }, [
    drivers,
    searchValue,
    statusFilter,
  ]);

  const filteredWaiters = useMemo(() => {
    const search =
      searchValue.trim().toLowerCase();

    return waiters.filter((waiter) => {
      const matchesSearch =
        search === "" ||
        [
          waiter.id,
          waiter.fullName,
          waiter.phone,
          waiter.nationalId,
          waiter.staffRole,
          waiter.reportsToName,
          waiter.eventRate,
          waiter.status,
        ].some((value) =>
          String(value)
            .toLowerCase()
            .includes(search)
        );

      return (
        matchesSearch &&
        (
          statusFilter ===
            "All Statuses" ||
          waiter.status ===
            statusFilter
        )
      );
    });
  }, [
    waiters,
    searchValue,
    statusFilter,
  ]);

  const activeStaff =
    activeTab === "drivers"
      ? filteredDrivers
      : activeTab === "waiters"
        ? filteredWaiters
        : [];

  const headDrivers = useMemo(
    () =>
      drivers.filter(
        (driver) =>
          driver.staffRole ===
            "Head Driver" &&
          Number(driver.id) !==
            Number(editingDriverId)
      ),
    [drivers, editingDriverId]
  );

  const headWaiters = useMemo(
    () =>
      waiters.filter(
        (waiter) =>
          waiter.staffRole ===
            "Head Waiter" &&
          Number(waiter.id) !==
            Number(editingWaiterId)
      ),
    [waiters, editingWaiterId]
  );

  const paymentSummaries = useMemo(() => {
    const grouped = new Map();

    payments.forEach((payment) => {
      const key = Number(payment.staffId);

      if (!grouped.has(key)) {
        grouped.set(key, {
          staffId: key,
          staffName: payment.staffName,
          staffType: payment.staffType,
          staffRole: payment.staffRole,
          totalAmount: 0,
          paidAmount: 0,
          remainingAmount: 0,
          events: [],
        });
      }

      const summary = grouped.get(key);
      const totalAmount = Number(payment.amount || 0);
      const paidAmount = Math.min(
        totalAmount,
        Number(payment.paidAmount || 0)
      );
      const remainingAmount = Math.max(
        totalAmount - paidAmount,
        0
      );

      summary.totalAmount += totalAmount;
      summary.paidAmount += paidAmount;
      summary.remainingAmount += remainingAmount;
      summary.events.push({
        ...payment,
        paidAmount,
        remainingAmount,
      });
    });

    return Array.from(grouped.values()).map(
      (summary) => ({
        ...summary,
        status:
          summary.remainingAmount <= 0
            ? "Paid"
            : summary.paidAmount > 0
              ? "Partial"
              : "Pending",
      })
    );
  }, [payments]);

  const filteredPaymentSummaries = useMemo(() => {
    const search =
      searchValue.trim().toLowerCase();

    return paymentSummaries.filter((summary) => {
      const matchesSearch =
        search === "" ||
        [
          summary.staffName,
          summary.staffType,
          summary.staffRole,
          summary.totalAmount,
          summary.paidAmount,
          summary.remainingAmount,
          summary.status,
          ...summary.events.flatMap((payment) => [
            payment.eventCode,
            payment.eventName,
            payment.eventDate,
          ]),
        ].some((value) =>
          String(value || "")
            .toLowerCase()
            .includes(search)
        );

      const matchesStatus =
        statusFilter === "All Statuses" ||
        summary.status === statusFilter;

      return matchesSearch && matchesStatus;
    });
  }, [
    paymentSummaries,
    searchValue,
    statusFilter,
  ]);

  const pendingPaymentTotal = useMemo(
    () =>
      paymentSummaries.reduce(
        (total, summary) =>
          total + Number(summary.remainingAmount || 0),
        0
      ),
    [paymentSummaries]
  );

  const handleRecordPayment = async (
    payment
  ) => {
    const key = `${payment.staffId}-${payment.eventId}`;
    const enteredAmount = Number(
      paymentDrafts[key] || 0
    );
    const remainingAmount = Number(
      payment.remainingAmount ??
        Math.max(
          Number(payment.amount || 0) -
            Number(payment.paidAmount || 0),
          0
        )
    );

    if (!enteredAmount || enteredAmount <= 0) {
      await showAlert({
        message: t("staffPage.errors.paymentAmountGreaterThanZero"),
      });
      return;
    }

    if (enteredAmount > remainingAmount) {
      await showAlert({
        message: t("staffPage.errors.paymentExceedsRemaining", {
          amount: remainingAmount.toLocaleString("en-US"),
          currency: t("staffPage.egp"),
        }),
      });
      return;
    }

    try {
      setPaymentSavingKey(key);

      const updated = await recordStaffPayment(
        payment,
        enteredAmount
      );

      setPayments((current) =>
        current.map((item) =>
          Number(item.staffId) ===
              Number(updated.staffId) &&
            Number(item.eventId) ===
              Number(updated.eventId)
            ? updated
            : item
        )
      );

      setPaymentDrafts((current) => ({
        ...current,
        [key]: "",
      }));

      setSelectedStaffPayment((current) => {
        if (!current) {
          return current;
        }

        const refreshedEvents = current.events.map(
          (item) =>
            Number(item.staffId) ===
                Number(updated.staffId) &&
              Number(item.eventId) ===
                Number(updated.eventId)
              ? {
                  ...updated,
                  remainingAmount: Math.max(
                    Number(updated.amount || 0) -
                      Number(updated.paidAmount || 0),
                    0
                  ),
                }
              : item
        );

        const totalAmount = refreshedEvents.reduce(
          (sum, item) =>
            sum + Number(item.amount || 0),
          0
        );
        const paidAmount = refreshedEvents.reduce(
          (sum, item) =>
            sum + Number(item.paidAmount || 0),
          0
        );
        const remainingAmount = Math.max(
          totalAmount - paidAmount,
          0
        );

        return {
          ...current,
          events: refreshedEvents,
          totalAmount,
          paidAmount,
          remainingAmount,
          status:
            remainingAmount <= 0
              ? "Paid"
              : paidAmount > 0
                ? "Partial"
                : "Pending",
        };
      });
    } catch (error) {
      showAlert({
        message:
          error.message ||
          t("staffPage.errors.couldNotRecordPayment"),
      });
    } finally {
      setPaymentSavingKey(null);
    }
  };

  const totalPages = Math.max(
    1,
    Math.ceil(
      activeStaff.length /
        staffPerPage
    )
  );

  const paginatedDrivers = useMemo(() => {
    const startIndex =
      (currentPage - 1) *
      staffPerPage;

    return filteredDrivers.slice(
      startIndex,
      startIndex + staffPerPage
    );
  }, [
    filteredDrivers,
    currentPage,
  ]);

  const paginatedWaiters = useMemo(() => {
    const startIndex =
      (currentPage - 1) *
      staffPerPage;

    return filteredWaiters.slice(
      startIndex,
      startIndex + staffPerPage
    );
  }, [
    filteredWaiters,
    currentPage,
  ]);

  useEffect(() => {
    setCurrentPage(1);
    setOpenActionId(null);
  }, [
    activeTab,
    searchValue,
    statusFilter,
  ]);

  useEffect(() => {
    if (currentPage > totalPages) {
      setCurrentPage(totalPages);
    }
  }, [
    currentPage,
    totalPages,
  ]);

  const toggleActionMenu = (
    event,
    staffId
  ) => {
    event.stopPropagation();

    if (openActionId === staffId) {
      setOpenActionId(null);
      return;
    }

    const buttonRect =
      event.currentTarget.getBoundingClientRect();

    const menuWidth = 125;
    const menuHeight = 54;
    const gap = 10;

    const availableSpaceBelow =
      window.innerHeight -
      buttonRect.bottom;

    const top =
      availableSpaceBelow >=
      menuHeight + gap
        ? buttonRect.bottom + gap
        : buttonRect.top -
          menuHeight -
          gap;

    const preferredLeft =
      buttonRect.right -
      menuWidth;

    const left = Math.max(
      12,
      Math.min(
        preferredLeft,
        window.innerWidth -
          menuWidth -
          12
      )
    );

    setActionMenuPosition({
      top: Math.max(12, top),
      left,
    });

    setOpenActionId(staffId);
  };

  const openEditDriver = async (driver) => {
    if (!canEdit) {
      showAlert({
        title: t("staffPage.errors.permissionDenied"),
        message:
          t("staffPage.errors.noEditPermission"),
        type: "warning",
      });

      return;
    }

    try {
      const nationalId = isAdmin
        ? await getStaffNationalId(
            driver.id
          )
        : driver.nationalId;

      setEditingDriverId(driver.id);
      setOpenActionId(null);
      setDriverForm({
        ...driver,
        nationalId,
        documents: {
          ...driver.documents,
        },
      });
      setShowDriverModal(true);
    } catch (error) {
      console.error(
        "Could not load driver National ID:",
        error
      );

      showAlert({
        message:
          error.message ||
          t("staffPage.errors.couldNotLoadStaff"),
      });
    }
  };

  const openEditWaiter = async (waiter) => {
    if (!canEdit) {
      showAlert({
        title: t("staffPage.errors.permissionDenied"),
        message:
          t("staffPage.errors.noEditPermission"),
        type: "warning",
      });

      return;
    }

    try {
      const nationalId = isAdmin
        ? await getStaffNationalId(
            waiter.id
          )
        : waiter.nationalId;

      setEditingWaiterId(waiter.id);
      setOpenActionId(null);
      setWaiterForm({
        ...waiter,
        nationalId,
        documents: {
          ...waiter.documents,
          healthCertificate: {
            ...waiter.documents
              .healthCertificate,
          },
          contract: {
            ...waiter.documents.contract,
          },
        },
      });
      setShowWaiterModal(true);
    } catch (error) {
      console.error(
        "Could not load waiter National ID:",
        error
      );

      showAlert({
        message:
          error.message ||
          t("staffPage.errors.couldNotLoadStaff"),
      });
    }
  };

  const handleDriverChange = (
    event
  ) => {
    const { name, value } =
      event.target;

    setDriverForm((current) => ({
      ...current,
      [name]: value,
    }));
  };

  const handleWaiterChange = (
    event
  ) => {
    const { name, value } =
      event.target;

    setWaiterForm((current) => ({
      ...current,
      [name]: value,
    }));
  };

  const saveDriver = async (event) => {
    event.preventDefault();

    if (
      !editingDriverId ||
      !canEdit
    ) {
      return;
    }

    if (
      !driverForm.fullName.trim() ||
      !driverForm.phone.trim() ||
      !driverForm.nationalId.trim() ||
      !driverForm.licenseNumber.trim() ||
      !driverForm.licenseExpiryDate ||
      !driverForm.carNumber.trim()
    ) {
      showAlert({
        message: t("staffPage.errors.completeDriver"),
      });
      return;
    }

    try {
      setSaving(true);

      const updated =
        await updateDriver(
          editingDriverId,
          driverForm
        );

      setDrivers((current) =>
        current.map((driver) =>
          driver.id === editingDriverId
            ? updated
            : driver
        )
      );

      setShowDriverModal(false);
      setEditingDriverId(null);
      setDriverForm(driverEmptyForm);
    } catch (error) {
      console.error(
        "Error saving driver:",
        error
      );

      showAlert({
        message: error.code === "23505"
          ? t("staffPage.errors.driverDuplicate")
          : error.message?.includes(
                "staff_phone_format_check"
              )
            ? i18n.language?.startsWith("ar")
              ? "يجب أن يتكون رقم الهاتف من 11 رقمًا بالضبط ويبدأ بـ 01."
              : "Phone number must be exactly 11 digits and start with 01."
            : error.message?.includes(
                  "staff_national_id_format_check"
                )
              ? i18n.language?.startsWith("ar")
                ? "يجب أن يتكون الرقم القومي من 14 رقمًا بالضبط."
                : "National ID must contain exactly 14 digits."
              : error.message ||
                t("staffPage.errors.couldNotSaveDriver"),
      });
    } finally {
      setSaving(false);
    }
  };

  const saveWaiter = async (event) => {
    event.preventDefault();

    if (
      !editingWaiterId ||
      !canEdit
    ) {
      return;
    }

    if (
      !waiterForm.fullName.trim() ||
      !waiterForm.phone.trim() ||
      !waiterForm.nationalId.trim()
    ) {
      showAlert({
        message: t("staffPage.errors.completeWaiter"),
      });
      return;
    }

    try {
      setSaving(true);

      const updated =
        await updateWaiter(
          editingWaiterId,
          waiterForm
        );

      setWaiters((current) =>
        current.map((waiter) =>
          waiter.id === editingWaiterId
            ? updated
            : waiter
        )
      );

      setShowWaiterModal(false);
      setEditingWaiterId(null);
      setWaiterForm(waiterEmptyForm);
    } catch (error) {
      console.error(
        "Error saving waiter:",
        error
      );

      showAlert({
        message: error.code === "23505"
          ? t("staffPage.errors.waiterDuplicate")
          : error.message?.includes(
                "staff_phone_format_check"
              )
            ? i18n.language?.startsWith("ar")
              ? "يجب أن يتكون رقم الهاتف من 11 رقمًا بالضبط ويبدأ بـ 01."
              : "Phone number must be exactly 11 digits and start with 01."
            : error.message?.includes(
                  "staff_national_id_format_check"
                )
              ? i18n.language?.startsWith("ar")
                ? "يجب أن يتكون الرقم القومي من 14 رقمًا بالضبط."
                : "National ID must contain exactly 14 digits."
              : error.message ||
                t("staffPage.errors.couldNotSaveWaiter"),
      });
    } finally {
      setSaving(false);
    }
  };

  const setDriverDocument = (
    field,
    file
  ) => {
    setDriverForm((current) => ({
      ...current,
      documents: {
        ...current.documents,
        [field]: file
          ? {
              name: file.name,
              file,
            }
          : null,
      },
    }));
  };

  const setWaiterDocument = (
    field,
    file
  ) => {
    setWaiterForm((current) => {
      if (
        field ===
        "healthCertificate"
      ) {
        return {
          ...current,
          documents: {
            ...current.documents,
            healthCertificate: {
              ...current.documents
                .healthCertificate,
              file: file
                ? {
                    name: file.name,
                    file,
                  }
                : null,
            },
          },
        };
      }

      if (field === "contract") {
        return {
          ...current,
          documents: {
            ...current.documents,
            contract: {
              ...current.documents
                .contract,
              file: file
                ? {
                    name: file.name,
                    file,
                  }
                : null,
            },
          },
        };
      }

      return {
        ...current,
        documents: {
          ...current.documents,
          [field]: file
            ? { name: file.name }
            : null,
        },
      };
    });
  };

  const setWaiterDate = (
    section,
    field,
    value
  ) => {
    setWaiterForm((current) => ({
      ...current,
      documents: {
        ...current.documents,
        [section]: {
          ...current.documents[
            section
          ],
          [field]: value,
        },
      },
    }));
  };

  const handleDeleteDriver = async (
    driverId
  ) => {
    if (!canDelete) {
      await showAlert({
        title: t("staffPage.errors.permissionDenied"),
        message:
          t("staffPage.errors.noDeletePermission"),
        type: "warning",
      });

      return;
    }

    const confirmed = await showConfirm({
      message: t("staffPage.confirm.deleteDriver"),
    });

    if (!confirmed) {
      return;
    }

    try {
      await deleteStaff(driverId);

      setDrivers((current) =>
        current.filter(
          (driver) =>
            driver.id !== driverId
        )
      );

      setOpenActionId(null);
    } catch (error) {
      showAlert({
        message: error.code === "23503"
          ? t("staffPage.errors.driverConnected")
          : error.message ||
              t("staffPage.errors.couldNotDeleteDriver"),
      });
    }
  };

  const handleDeleteWaiter = async (
    waiterId
  ) => {
    if (!canDelete) {
      await showAlert({
        title: t("staffPage.errors.permissionDenied"),
        message:
          t("staffPage.errors.noDeletePermission"),
        type: "warning",
      });

      return;
    }

    const confirmed = await showConfirm({
      message: t("staffPage.confirm.deleteWaiter"),
    });

    if (!confirmed) {
      return;
    }

    try {
      await deleteStaff(waiterId);

      setWaiters((current) =>
        current.filter(
          (waiter) =>
            waiter.id !== waiterId
        )
      );

      setOpenActionId(null);
    } catch (error) {
      showAlert({
        message: error.code === "23503"
          ? t("staffPage.errors.waiterConnected")
          : error.message ||
              t("staffPage.errors.couldNotDeleteWaiter"),
      });
    }
  };

  return (
    <div className="dashboard-page">
      <Sidebar activePage="staff" />

      <main className="staff-main">
        <Topbar
          searchValue={searchValue}
          onSearchChange={setSearchValue}
        />

        <section className="staff-title-section">
          <div>
            <h1>{t("staffPage.title")}</h1>
            <p>
              {t("staffPage.subtitle")}
            </p>
          </div>
        </section>

        <section className="staff-table-card">
          <div className="staff-toolbar">
            <div className="staff-tabs">
              <button
                type="button"
                className={
                  activeTab === "drivers"
                    ? "active"
                    : ""
                }
                onClick={() =>
                  setActiveTab("drivers")
                }
              >
                {t("staffPage.tabs.drivers")}
              </button>

              <button
                type="button"
                className={
                  activeTab === "waiters"
                    ? "active"
                    : ""
                }
                onClick={() =>
                  setActiveTab("waiters")
                }
              >
                {t("staffPage.tabs.waiters")}
              </button>

              <button
                type="button"
                className={
                  activeTab === "payments"
                    ? "active"
                    : ""
                }
                onClick={() => {
                  setActiveTab("payments");
                  setStatusFilter(
                    "All Statuses"
                  );
                }}
              >
                {t("staffPage.tabs.payments")}
              </button>
            </div>

            <div className="staff-filters">
              <div className="staff-search-box">
                <FiSearch />
                <input
                  type="text"
                  placeholder={
                    activeTab === "drivers"
                      ? t("staffPage.search.drivers")
                      : activeTab === "waiters"
                        ? t("staffPage.search.waiters")
                        : t("staffPage.search.payments")
                  }
                  value={searchValue}
                  onChange={(event) =>
                    setSearchValue(
                      event.target.value
                    )
                  }
                />
              </div>

              <select
                value={statusFilter}
                onChange={(event) =>
                  setStatusFilter(
                    event.target.value
                  )
                }
              >
                <option value="All Statuses">{t("staffPage.status.all")}</option>

                {activeTab === "payments" ? (
                  <>
                    <option value="Pending">
                      {t("staffPage.status.pending")}
                    </option>
                    <option value="Partial">
                      {t("staffPage.status.partial")}
                    </option>
                    <option value="Paid">
                      {t("staffPage.status.paid")}
                    </option>
                  </>
                ) : (
                  <>
                    <option value="Active">
                      {t("staffPage.status.active")}
                    </option>
                    <option value="Inactive">
                      {t("staffPage.status.inactive")}
                    </option>
                    <option value="Suspended">
                      {t("staffPage.status.suspended")}
                    </option>
                  </>
                )}
              </select>
            </div>
          </div>

          {activeTab === "drivers" ? (
            <div className="staff-table-wrapper">
              <table>
                <thead>
                  <tr>
                    <th>{t("staffPage.table.driver")}</th>
                    <th>{t("staffPage.table.phone")}</th>
                    <th>{t("staffPage.table.nationalId")}</th>
                    <th>{t("staffPage.table.license")}</th>
                    <th>{t("staffPage.table.licenseExpiry")}</th>
                    <th>{t("staffPage.table.carNumber")}</th>
                    <th>{t("staffPage.table.carType")}</th>
                    <th>{t("staffPage.table.role")}</th>
                    <th>{t("staffPage.table.reportsTo")}</th>
                    <th>{t("staffPage.table.eventRate")}</th>
                    <th>{t("staffPage.table.status")}</th>
                    <th>{t("staffPage.table.actions")}</th>
                  </tr>
                </thead>

                <tbody>
                  {loading ? (
                    <tr>
                      <td
                        colSpan="12"
                        className="staff-empty-state"
                      >
                        {t("staffPage.loadingDrivers")}
                      </td>
                    </tr>
                  ) : paginatedDrivers.map(
                    (driver) => (
                      <tr key={driver.id}>
                        <td>
                          <div className="staff-name-cell">
                            <div className="staff-row-icon">
                              <FiTruck />
                            </div>
                            <div>
                              <strong>
                                {
                                  driver.fullName
                                }
                              </strong>
                              <span>
                                {driver.id}
                              </span>
                            </div>
                          </div>
                        </td>
                        <td>{driver.phone}</td>
                        <td>
                          {maskNationalId(
                            driver.nationalId
                          )}
                        </td>
                        <td>
                          {
                            driver.licenseNumber
                          }
                        </td>
                        <td>
                          {formatDate(
                            driver.licenseExpiryDate
                          )}
                        </td>
                        <td>
                          {driver.carNumber}
                        </td>
                        <td>
                          {driver.carType === "Van"
                            ? t("staffPage.values.van")
                            : driver.carType === "Truck"
                              ? t("staffPage.values.truck")
                              : driver.carType === "Pickup"
                                ? t("staffPage.values.pickup")
                                : driver.carType === "Refrigerated Truck"
                                  ? t("staffPage.values.refrigeratedTruck")
                                  : t("staffPage.values.other")}
                        </td>
                        <td>
                          {driver.staffRole === "Head Driver" ? t("staffPage.values.headDriver") : t("staffPage.values.driver")}
                        </td>
                        <td>
                          {driver.reportsToName ||
                            "-"}
                        </td>
                        <td>
                          {Number(
                            driver.eventRate || 0
                          ).toLocaleString(
                            "en-US"
                          )}{" "}
                          {t("staffPage.egp")}
                        </td>
                        <td>
                          <span
                            className={`staff-status ${driver.status.toLowerCase()}`}
                          >
                            {driver.status === "Active" ? t("staffPage.status.active") : driver.status === "Inactive" ? t("staffPage.status.inactive") : driver.status === "Suspended" ? t("staffPage.status.suspended") : driver.status}
                          </span>
                        </td>
                        <td className="staff-action-cell">
                          <div className="staff-actions">
                            <button
                              type="button"
                              onClick={() =>
                                openEditDriver(
                                  driver
                                )
                              }
                            >
                              <FiEdit2 />
                            </button>

                            <div className="staff-more-wrapper">
                              <button
                                type="button"
                                className="staff-more-button"
                                onClick={(event) =>
                                  toggleActionMenu(
                                    event,
                                    driver.id
                                  )
                                }
                              >
                                <FiMoreVertical />
                              </button>

                              {openActionId ===
                                driver.id && (
                                <div
                                  className="staff-action-menu"
                                  style={{
                                    top:
                                      actionMenuPosition.top,
                                    left:
                                      actionMenuPosition.left,
                                  }}
                                >
                                  <button
                                    type="button"
                                    className="staff-delete-action"
                                    onClick={() => {
                                      handleDeleteDriver(
                                        driver.id
                                      );
                                      setOpenActionId(
                                        null
                                      );
                                    }}
                                  >
                                    <FiTrash2 />
                                    {t("staffPage.actions.delete")}
                                  </button>
                                </div>
                              )}
                            </div>
                          </div>
                        </td>
                      </tr>
                    )
                  )}
                </tbody>
              </table>
            </div>
          ) : activeTab === "waiters" ? (
            <div className="staff-table-wrapper">
              <table>
                <thead>
                  <tr>
                    <th>{t("staffPage.table.waiter")}</th>
                    <th>{t("staffPage.table.phone")}</th>
                    <th>{t("staffPage.table.nationalId")}</th>
                    <th>{t("staffPage.table.healthExpiry")}</th>
                    <th>{t("staffPage.table.contractEnd")}</th>
                    <th>{t("staffPage.table.documents")}</th>
                    <th>{t("staffPage.table.role")}</th>
                    <th>{t("staffPage.table.reportsTo")}</th>
                    <th>{t("staffPage.table.eventRate")}</th>
                    <th>{t("staffPage.table.status")}</th>
                    <th>{t("staffPage.table.actions")}</th>
                  </tr>
                </thead>

                <tbody>
                  {loading ? (
                    <tr>
                      <td
                        colSpan="11"
                        className="staff-empty-state"
                      >
                        {t("staffPage.loadingWaiters")}
                      </td>
                    </tr>
                  ) : paginatedWaiters.map(
                    (waiter) => {
                      const count = [
                        waiter.documents
                          .personalPhoto,
                        waiter.documents
                          .nationalIdImage,
                        waiter.documents
                          .healthCertificate
                          .file,
                        waiter.documents
                          .contract.file,
                      ].filter(Boolean).length;

                      return (
                        <tr key={waiter.id}>
                          <td>
                            <div className="staff-name-cell">
                              <div className="staff-row-icon">
                                <FiUsers />
                              </div>
                              <div>
                                <strong>
                                  {
                                    waiter.fullName
                                  }
                                </strong>
                                <span>
                                  {waiter.id}
                                </span>
                              </div>
                            </div>
                          </td>
                          <td>{waiter.phone}</td>
                          <td>
                            {maskNationalId(
                              waiter.nationalId
                            )}
                          </td>
                          <td>
                            {formatDate(
                              waiter.documents
                                .healthCertificate
                                .expiryDate
                            )}
                          </td>
                          <td>
                            {formatDate(
                              waiter.documents
                                .contract.endDate
                            )}
                          </td>
                          <td>{count}/4</td>
                          <td>
                            {waiter.staffRole === "Head Waiter" ? t("staffPage.values.headWaiter") : t("staffPage.values.waiter")}
                          </td>
                          <td>
                            {waiter.reportsToName ||
                              "-"}
                          </td>
                          <td>
                            {Number(
                              waiter.eventRate ||
                                0
                            ).toLocaleString(
                              "en-US"
                            )}{" "}
                            {t("staffPage.egp")}
                          </td>
                          <td>
                            <span
                              className={`staff-status ${waiter.status.toLowerCase()}`}
                            >
                              {waiter.status === "Active" ? t("staffPage.status.active") : waiter.status === "Inactive" ? t("staffPage.status.inactive") : waiter.status === "Suspended" ? t("staffPage.status.suspended") : waiter.status}
                            </span>
                          </td>
                          <td className="staff-action-cell">
                            <div className="staff-actions">
                              <button
                                type="button"
                                onClick={() =>
                                  openEditWaiter(
                                    waiter
                                  )
                                }
                              >
                                <FiEdit2 />
                              </button>

                              <div className="staff-more-wrapper">
                                <button
                                  type="button"
                                  className="staff-more-button"
                                  onClick={(event) =>
                                    toggleActionMenu(
                                      event,
                                      waiter.id
                                    )
                                  }
                                >
                                  <FiMoreVertical />
                                </button>

                                {openActionId ===
                                  waiter.id && (
                                  <div
                                    className="staff-action-menu"
                                    style={{
                                      top:
                                        actionMenuPosition.top,
                                      left:
                                        actionMenuPosition.left,
                                    }}
                                  >
                                    <button
                                      type="button"
                                      className="staff-delete-action"
                                      onClick={() => {
                                        handleDeleteWaiter(
                                          waiter.id
                                        );
                                        setOpenActionId(
                                          null
                                        );
                                      }}
                                    >
                                      <FiTrash2 />
                                      {t("staffPage.actions.delete")}
                                    </button>
                                  </div>
                                )}
                              </div>
                            </div>
                          </td>
                        </tr>
                      );
                    }
                  )}
                </tbody>
              </table>
            </div>
          ) : (
            <>
              <div className="staff-payment-summary">
                <div>
                  <span>
                    {t("staffPage.payments.pendingPayments")}
                  </span>
                  <strong>
                    {pendingPaymentTotal.toLocaleString(
                      "en-US",
                      {
                        maximumFractionDigits: 2,
                      }
                    )}{" "}
                    {t("staffPage.egp")}
                  </strong>
                </div>

                <small>
                  {t("staffPage.payments.calculatedPerEvent")}
                </small>
              </div>

              <div className="staff-table-wrapper">
                <table>
                  <thead>
                    <tr>
                      <th>{t("staffPage.table.staff")}</th>
                      <th>{t("staffPage.table.type")}</th>
                      <th>{t("staffPage.table.totalAmount")}</th>
                      <th>{t("staffPage.table.paid")}</th>
                      <th>{t("staffPage.table.remaining")}</th>
                      <th>{t("staffPage.table.status")}</th>
                      <th>{t("staffPage.table.action")}</th>
                    </tr>
                  </thead>

                  <tbody>
                    {paymentsLoading ? (
                      <tr>
                        <td
                          colSpan="7"
                          className="staff-empty-state"
                        >
                          {t("staffPage.loadingPayments")}
                        </td>
                      </tr>
                    ) : filteredPaymentSummaries.length >
                      0 ? (
                      filteredPaymentSummaries.map(
                        (summary) => (
                          <tr key={summary.staffId}>
                            <td>
                              <div className="staff-name-cell">
                                <div className="staff-row-icon">
                                  {summary.staffType ===
                                  "Driver" ? (
                                    <FiTruck />
                                  ) : (
                                    <FiUsers />
                                  )}
                                </div>
                                <div>
                                  <strong>
                                    {summary.staffName}
                                  </strong>
                                  <span>
                                    {summary.staffRole === "Head Driver"
                                      ? t("staffPage.values.headDriver")
                                      : summary.staffRole === "Driver"
                                        ? t("staffPage.values.driver")
                                        : summary.staffRole === "Head Waiter"
                                          ? t("staffPage.values.headWaiter")
                                          : t("staffPage.values.waiter")}
                                  </span>
                                </div>
                              </div>
                            </td>
                            <td>
                              {summary.staffType === "Driver"
                                ? t("staffPage.values.driver")
                                : t("staffPage.values.waiter")}
                            </td>
                            <td>
                              <strong>
                                {Number(
                                  summary.totalAmount || 0
                                ).toLocaleString("en-US")} {t("staffPage.egp")}
                              </strong>
                            </td>
                            <td>
                              {Number(
                                summary.paidAmount || 0
                              ).toLocaleString("en-US")} {t("staffPage.egp")}
                            </td>
                            <td>
                              <strong>
                                {Number(
                                  summary.remainingAmount || 0
                                ).toLocaleString("en-US")} {t("staffPage.egp")}
                              </strong>
                            </td>
                            <td>
                              <span
                                className={`staff-payment-status ${String(
                                  summary.status
                                ).toLowerCase()}`}
                              >
                                {summary.status === "Paid"
                                  ? t("staffPage.status.paid")
                                  : summary.status === "Partial"
                                    ? t("staffPage.status.partial")
                                    : t("staffPage.status.pending")}
                              </span>
                            </td>
                            <td>
                              <button
                                type="button"
                                className="staff-payment-button"
                                onClick={() =>
                                  setSelectedStaffPayment(
                                    summary
                                  )
                                }
                              >
                                View / Pay
                              </button>
                            </td>
                          </tr>
                        )
                      )
                    ) : (
                      <tr>
                        <td
                          colSpan="7"
                          className="staff-empty-state"
                        >
                          {t("staffPage.payments.noResults")}
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </>
          )}

          {activeTab !== "payments" && (
          <div className="staff-pagination">
            <p>
              Showing{" "}
              {activeStaff.length === 0
                ? 0
                : (currentPage - 1) *
                    staffPerPage +
                  1}
              {" - "}
              {Math.min(
                currentPage *
                  staffPerPage,
                activeStaff.length
              )}{" "}
              of {activeStaff.length}{" "}
              {activeTab === "drivers"
                ? t("staffPage.pagination.drivers")
                : t("staffPage.pagination.waiters")}
            </p>

            <div>
              <button
                type="button"
                disabled={
                  currentPage === 1
                }
                onClick={() =>
                  setCurrentPage(
                    (page) => page - 1
                  )
                }
              >
                 ‹
              </button>

              {Array.from(
                {
                  length: totalPages,
                },
                (_, index) =>
                  index + 1
              ).map((pageNumber) => (
                <button
                  key={pageNumber}
                  type="button"
                  className={
                    currentPage ===
                    pageNumber
                      ? "active"
                      : ""
                  }
                  onClick={() =>
                    setCurrentPage(
                      pageNumber
                    )
                  }
                >
                  {pageNumber}
                </button>
              ))}

              <button
                type="button"
                disabled={
                  currentPage ===
                  totalPages
                }
                onClick={() =>
                  setCurrentPage(
                    (page) => page + 1
                  )
                }
              >
                ›
              </button>
            </div>
          </div>
          )}
        </section>
      </main>

      {showDriverModal && (
        <div
          className="staff-modal-overlay"
          onMouseDown={() =>
            setShowDriverModal(false)
          }
        >
          <form
            className="staff-modal"
            onSubmit={saveDriver}
            onMouseDown={(event) =>
              event.stopPropagation()
            }
          >
            <div className="staff-modal-header">
              <div>
                <h2>
{t("staffPage.driverModal.title")}
                </h2>
                <p>
                  {t("staffPage.driverModal.subtitle")}
                </p>
              </div>
              <button
                type="button"
                onClick={() =>
                  setShowDriverModal(false)
                }
                disabled={saving}
              >
                <FiX />
              </button>
            </div>

            <div className="staff-form-grid">
              {[
                ["fullName", t("staffPage.fields.fullName")],
                ["phone", t("staffPage.fields.phoneNumber")],
                ["nationalId", t("staffPage.fields.nationalId")],
                [
                  "licenseNumber",
                  t("staffPage.fields.licenseNumber"),
                ],
                ["carNumber", t("staffPage.fields.carNumber")],
              ].map(([name, label]) => (
                <label key={name}>
                  {label}
                  <input
                    name={name}
                    value={
                      driverForm[name]
                    }
                    disabled={
                      name === "nationalId" &&
                      !isAdmin
                    }
                    onChange={
                      handleDriverChange
                    }
                  />
                </label>
              ))}

              <label>
                {t("staffPage.fields.licenseExpiryDate")}
                <input
                  type="date"
                  name="licenseExpiryDate"
                  value={
                    driverForm.licenseExpiryDate
                  }
                  onChange={
                    handleDriverChange
                  }
                />
              </label>

              <label>
                {t("staffPage.fields.carType")}
                <select
                  name="carType"
                  value={
                    driverForm.carType
                  }
                  onChange={
                    handleDriverChange
                  }
                >
                  <option value="Van">
                    {t("staffPage.values.van")}
                  </option>
                  <option value="Truck">
                    {t("staffPage.values.truck")}
                  </option>
                  <option value="Pickup">
                    {t("staffPage.values.pickup")}
                  </option>
                  <option value="Refrigerated Truck">
                    {t("staffPage.values.refrigeratedTruck")}
                  </option>
                  <option value="Other">
                    {t("staffPage.values.other")}
                  </option>
                </select>
              </label>

              <label>
                {t("staffPage.fields.status")}
                <select
                  name="status"
                  value={driverForm.status}
                  onChange={
                    handleDriverChange
                  }
                >
                  <option value="Active">
                    {t("staffPage.status.active")}
                  </option>
                  <option value="Inactive">
                    {t("staffPage.status.inactive")}
                  </option>
                  <option value="Suspended">
                    {t("staffPage.status.suspended")}
